@component.add(
    name="Renters adopting PV",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 2,
        "rented_buildings_with_pv": 4,
        "heating_solution": 16,
        "probability_adoption_pv_renters": 6,
        "rented_buildings_with_rcpv": 4,
        "rented_buildings_with_rcp": 4,
        "share_of_owned_houses": 6,
        "share_of_buildings_with_suitable_roof": 6,
        "share_urban_buildings": 1,
        "rented_buildings_with_rcpv_pvno": 3,
        "energy_community_scenario": 2,
    },
)
def renters_adopting_pv():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
        },
        ["District", "HS", "Performance", "Type"],
    )
    except_subs = xr.ones_like(value, dtype=bool)
    except_subs.loc[:, :, :, ["MFH"]] = False
    value.values[except_subs.values] = (
        if_then_else(
            time() < 2025,
            lambda: if_then_else(
                (
                    sum(
                        heating_solution()
                        .loc[:, :, :, :, "PVyes", :]
                        .reset_coords(drop=True)
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "Performance!",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "Performance!", "Battery!"],
                    )
                    > 0
                )
                .expand_dims({"HS": _subscript_dict["HS"]}, 2)
                .expand_dims({"Performance": _subscript_dict["Performance"]}, 3),
                lambda: (
                    (
                        sum(
                            heating_solution().rename(
                                {"PVpanel": "PVpanel!", "Battery": "Battery!"}
                            ),
                            dim=["PVpanel!", "Battery!"],
                        )
                        * share_of_buildings_with_suitable_roof()
                        * (1 - share_of_owned_houses())
                        - sum(
                            heating_solution()
                            .loc[:, :, :, :, "PVyes", :]
                            .reset_coords(drop=True)
                            .rename({"Battery": "Battery!"}),
                            dim=["Battery!"],
                        )
                        * (
                            rented_buildings_with_pv()
                            + rented_buildings_with_rcp()
                            + rented_buildings_with_rcpv()
                        )
                        / sum(
                            heating_solution()
                            .loc[:, :, :, :, "PVyes", :]
                            .reset_coords(drop=True)
                            .rename(
                                {
                                    "HS": "HS!",
                                    "Performance": "Performance!",
                                    "Battery": "Battery!",
                                }
                            ),
                            dim=["HS!", "Performance!", "Battery!"],
                        )
                    )
                    * probability_adoption_pv_renters()
                ).transpose("District", "Type", "HS", "Performance"),
                lambda: (
                    sum(
                        heating_solution().rename(
                            {"PVpanel": "PVpanel!", "Battery": "Battery!"}
                        ),
                        dim=["PVpanel!", "Battery!"],
                    )
                    * share_of_buildings_with_suitable_roof()
                    * (1 - share_of_owned_houses())
                    * probability_adoption_pv_renters()
                ).transpose("District", "Type", "HS", "Performance"),
            ),
            lambda: (
                (
                    sum(
                        heating_solution().rename(
                            {"PVpanel": "PVpanel!", "Battery": "Battery!"}
                        ),
                        dim=["PVpanel!", "Battery!"],
                    )
                    * share_of_buildings_with_suitable_roof()
                    * (1 - share_of_owned_houses())
                    - sum(
                        heating_solution()
                        .loc[:, :, :, :, "PVyes", :]
                        .reset_coords(drop=True)
                        .rename({"Battery": "Battery!"}),
                        dim=["Battery!"],
                    )
                    * (
                        rented_buildings_with_pv()
                        + rented_buildings_with_rcp()
                        + rented_buildings_with_rcpv()
                        + rented_buildings_with_rcpv_pvno()
                    )
                    / sum(
                        heating_solution()
                        .loc[:, :, :, :, "PVyes", :]
                        .reset_coords(drop=True)
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "Performance!",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "Performance!", "Battery!"],
                    )
                )
                * probability_adoption_pv_renters()
                * (1 - share_urban_buildings())
                * energy_community_scenario()
                - (
                    sum(
                        heating_solution().rename(
                            {"PVpanel": "PVpanel!", "Battery": "Battery!"}
                        ),
                        dim=["PVpanel!", "Battery!"],
                    )
                    * share_of_buildings_with_suitable_roof()
                    * (1 - share_of_owned_houses())
                    - sum(
                        heating_solution()
                        .loc[:, :, :, :, "PVyes", :]
                        .reset_coords(drop=True)
                        .rename({"Battery": "Battery!"}),
                        dim=["Battery!"],
                    )
                    * (
                        rented_buildings_with_pv()
                        + rented_buildings_with_rcp()
                        + rented_buildings_with_rcpv()
                        + rented_buildings_with_rcpv_pvno()
                    )
                    / sum(
                        heating_solution()
                        .loc[:, :, :, :, "PVyes", :]
                        .reset_coords(drop=True)
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "Performance!",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "Performance!", "Battery!"],
                    )
                )
                * probability_adoption_pv_renters()
                * (energy_community_scenario() - 1)
            ).transpose("District", "Type", "HS", "Performance"),
        )
        .transpose("District", "HS", "Performance", "Type")
        .values[except_subs.values]
    )
    value.loc[:, :, :, ["MFH"]] = (
        if_then_else(
            time() < 2018,
            lambda: if_then_else(
                (
                    sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", "PVyes", :]
                        .reset_coords(drop=True)
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "Performance!",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "Performance!", "Battery!"],
                    )
                    > 0
                )
                .expand_dims({"HS": _subscript_dict["HS"]}, 1)
                .expand_dims({"Performance": _subscript_dict["Performance"]}, 2),
                lambda: (
                    sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", :, :]
                        .reset_coords(drop=True)
                        .rename({"PVpanel": "PVpanel!", "Battery": "Battery!"}),
                        dim=["PVpanel!", "Battery!"],
                    )
                    * share_of_buildings_with_suitable_roof()
                    .loc[:, "MFH"]
                    .reset_coords(drop=True)
                    * (1 - float(share_of_owned_houses().loc["MFH"]))
                    - sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", "PVyes", :]
                        .reset_coords(drop=True)
                        .rename({"Battery": "Battery!"}),
                        dim=["Battery!"],
                    )
                    * (
                        rented_buildings_with_pv().loc[:, "MFH"].reset_coords(drop=True)
                        + rented_buildings_with_rcp()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                        + rented_buildings_with_rcpv()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                        + rented_buildings_with_rcpv_pvno()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                    )
                    / sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", "PVyes", :]
                        .reset_coords(drop=True)
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "Performance!",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "Performance!", "Battery!"],
                    )
                )
                * probability_adoption_pv_renters()
                .loc[:, :, :, "MFH"]
                .reset_coords(drop=True),
                lambda: sum(
                    heating_solution()
                    .loc[:, :, :, "MFH", :, :]
                    .reset_coords(drop=True)
                    .rename({"PVpanel": "PVpanel!", "Battery": "Battery!"}),
                    dim=["PVpanel!", "Battery!"],
                )
                * share_of_buildings_with_suitable_roof()
                .loc[:, "MFH"]
                .reset_coords(drop=True)
                * (1 - float(share_of_owned_houses().loc["MFH"]))
                * probability_adoption_pv_renters()
                .loc[:, :, :, "MFH"]
                .reset_coords(drop=True),
            ),
            lambda: xr.DataArray(
                0,
                {
                    "District": _subscript_dict["District"],
                    "HS": _subscript_dict["HS"],
                    "Performance": _subscript_dict["Performance"],
                },
                ["District", "HS", "Performance"],
            ),
        )
        .expand_dims({"Type": ["MFH"]}, 3)
        .values
    )
    return value


