    value.loc[:, :, :, ["MFH"]] = (
        if_then_else(
            time() < 2018,
            lambda: xr.DataArray(
                0,
                {
                    "District": _subscript_dict["District"],
                    "HS": _subscript_dict["HS"],
                    "Performance": _subscript_dict["Performance"],
                },
                ["District", "HS", "Performance"],
            ),
            lambda: if_then_else(
                time() < 2025,
                lambda: (
                    sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", :, :]
                        .reset_coords(drop=True)
                        .rename({"PVpanel": "PVpanel!", "Battery": "Battery!"}),
                        dim=["PVpanel!", "Battery!"],
                    )
                    * share_of_buildings_with_suitable_roof()
                    .loc[:, "MFH"]
                    .reset_coords(drop=True)
                    * (1 - float(share_of_owned_houses().loc["MFH"]))
                    - sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", "PVyes", :]
                        .reset_coords(drop=True)
                        .rename({"Battery": "Battery!"}),
                        dim=["Battery!"],
                    )
                    * (
                        rented_buildings_with_pv().loc[:, "MFH"].reset_coords(drop=True)
                        + rented_buildings_with_rcp()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                        + rented_buildings_with_rcpv()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                    )
                    / sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", "PVyes", :]
                        .reset_coords(drop=True)
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "Performance!",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "Performance!", "Battery!"],
                    )
                )
                * probability_adoption_rcp_renters()
                .loc[:, :, :, "MFH"]
                .reset_coords(drop=True),
                lambda: (
                    sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", :, :]
                        .reset_coords(drop=True)
                        .rename({"PVpanel": "PVpanel!", "Battery": "Battery!"}),
                        dim=["PVpanel!", "Battery!"],
                    )
                    * share_of_buildings_with_suitable_roof()
                    .loc[:, "MFH"]
                    .reset_coords(drop=True)
                    * (1 - float(share_of_owned_houses().loc["MFH"]))
                    - sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", "PVyes", :]
                        .reset_coords(drop=True)
                        .rename({"Battery": "Battery!"}),
                        dim=["Battery!"],
                    )
                    * (
                        rented_buildings_with_pv().loc[:, "MFH"].reset_coords(drop=True)
                        + rented_buildings_with_rcp()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                        + rented_buildings_with_rcpv()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                        + rented_buildings_with_rcpv_pvno()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                    )
                    / sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", "PVyes", :]
                        .reset_coords(drop=True)
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "Performance!",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "Performance!", "Battery!"],
                    )
                )
                * probability_adoption_rcp_renters()
                .loc[:, :, :, "MFH"]
                .reset_coords(drop=True)
                * (1 - share_urban_buildings().loc[:, "MFH"].reset_coords(drop=True))
                * energy_community_scenario()
                - (
                    sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", :, :]
                        .reset_coords(drop=True)
                        .rename({"PVpanel": "PVpanel!", "Battery": "Battery!"}),
                        dim=["PVpanel!", "Battery!"],
                    )
                    * share_of_buildings_with_suitable_roof()
                    .loc[:, "MFH"]
                    .reset_coords(drop=True)
                    * (1 - float(share_of_owned_houses().loc["MFH"]))
                    - sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", "PVyes", :]
                        .reset_coords(drop=True)
                        .rename({"Battery": "Battery!"}),
                        dim=["Battery!"],
                    )
                    * (
                        rented_buildings_with_pv().loc[:, "MFH"].reset_coords(drop=True)
                        + rented_buildings_with_rcp()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                        + rented_buildings_with_rcpv()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                        + rented_buildings_with_rcpv_pvno()
                        .loc[:, "MFH"]
                        .reset_coords(drop=True)
                    )
                    / sum(
                        heating_solution()
                        .loc[:, :, :, "MFH", "PVyes", :]
                        .reset_coords(drop=True)
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "Performance!",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "Performance!", "Battery!"],
                    )
                )
                * probability_adoption_rcp_renters()
                .loc[:, :, :, "MFH"]
                .reset_coords(drop=True)
                * (energy_community_scenario() - 1),
            ),
        )
        .expand_dims({"Type": ["MFH"]}, 3)
        .values
    )
    return value


