@component.add(
    name="Peer effect V factor",
    subscripts=["Vechicle"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"peer_effect_v": 2, "peer_effect_v_weight": 2},
)
def peer_effect_v_factor():
    """
    LOG( SUM(Peer effect V[AlternativeV!]) , 10 ) * Peer effect V weight LOG( MAX( Average MS by Vehicle delay[AlternativeV] , 1e-05 ) , 10 ) * Peer effect V weight
    """
    value = xr.DataArray(
        np.nan, {"Vechicle": _subscript_dict["Vechicle"]}, ["Vechicle"]
    )
    value.loc[_subscript_dict["AlternativeV"]] = (
        (
            np.log(
                np.maximum(
                    peer_effect_v()
                    .loc[_subscript_dict["AlternativeV"]]
                    .rename({"Vechicle": "AlternativeV"}),
                    0.0001,
                )
            )
            / np.log(10)
        )
        * peer_effect_v_weight()
    ).values
    value.loc[_subscript_dict["ICE"]] = (
        (
            np.log(
                peer_effect_v().loc[_subscript_dict["ICE"]].rename({"Vechicle": "ICE"})
            )
            / np.log(10)
        )
        * peer_effect_v_weight()
    ).values
    return value


