@component.add(
    name="Hydro additional hourly supply winter",
    subscripts=["Month", "Hour"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 2, "provvedimento_17": 1, "hour_factor_hs": 2},
)
def hydro_additional_hourly_supply_winter():
    value = xr.DataArray(
        np.nan,
        {"Month": _subscript_dict["Month"], "Hour": _subscript_dict["Hour"]},
        ["Month", "Hour"],
    )
    value.loc[_subscript_dict["Winter"], :] = if_then_else(
        time() < 2026,
        lambda: xr.DataArray(
            0,
            {"Winter": _subscript_dict["Winter"], "Hour": _subscript_dict["Hour"]},
            ["Winter", "Hour"],
        ),
        lambda: provvedimento_17()
        * 89
        / 365
        * 12
        * hour_factor_hs().loc[_subscript_dict["Winter"], :].rename({"Month": "Winter"})
        / sum(
            hour_factor_hs()
            .loc[_subscript_dict["Winter"], :]
            .rename({"Month": "Winter!", "Hour": "Hour!"}),
            dim=["Winter!", "Hour!"],
        )
        * (time() - 2026)
        / (2050 - 2026),
    ).values
    value.loc[_subscript_dict["Summer"], :] = 0
    return value


