def hourly_exported_electricity():
    value = xr.DataArray(
        np.nan,
        {
            "Month": _subscript_dict["Month"],
            "Hour": _subscript_dict["Hour"],
            "Supplier": _subscript_dict["Supplier"],
        },
        ["Month", "Hour", "Supplier"],
    )
    except_subs = xr.ones_like(value, dtype=bool)
    except_subs.loc[:, :, ["Import"]] = False
    value.values[except_subs.values] = (
        hourly_available_supply_by_supplier() - electricity_dispatched()
    ).values[except_subs.values]
    value.loc[:, :, ["Import"]] = 0
    return value


