@component.add(
    name="Building construction by archetype",
    subscripts=["District", "Performance", "Type", "PVpanel"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 3,
        "buildings_construction": 3,
        "heating_solution": 6,
        "coeff_roof_suitability": 3,
        "res_total_construction_by_perf_type_district": 3,
        "pv_reg_scenario": 1,
        "building_construction_by_archetype": 2,
    },
)
def building_construction_by_archetype():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
            "PVpanel": _subscript_dict["PVpanel"],
        },
        ["District", "Performance", "Type", "PVpanel"],
    )
    value.loc[:, _subscript_dict["PerformanceLow"], :, :] = 0
    value.loc[:, _subscript_dict["PerformanceHigh"], :, ["PVyes"]] = (
        if_then_else(
            time() < 2025,
            lambda: if_then_else(
                sum(
                    heating_solution()
                    .loc[:, :, _subscript_dict["PerformanceHigh"], :, :, :]
                    .rename(
                        {
                            "HS": "HS!",
                            "Performance": "PerformanceHigh",
                            "PVpanel": "PVpanel!",
                            "Battery": "Battery!",
                        }
                    ),
                    dim=["HS!", "PVpanel!", "Battery!"],
                )
                > 0,
                lambda: (
                    buildings_construction()
                    .loc[:, :, _subscript_dict["PerformanceHigh"]]
                    .rename({"Performance": "PerformanceHigh"})
                    * sum(
                        heating_solution()
                        .loc[:, :, _subscript_dict["PerformanceHigh"], :, "PVyes", :]
                        .reset_coords(drop=True)
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "PerformanceHigh",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "Battery!"],
                    ).transpose("Type", "District", "PerformanceHigh")
                    / (
                        sum(
                            heating_solution()
                            .loc[:, :, _subscript_dict["PerformanceHigh"], :, :, :]
                            .rename(
                                {
                                    "HS": "HS!",
                                    "Performance": "PerformanceHigh",
                                    "PVpanel": "PVpanel!",
                                    "Battery": "Battery!",
                                }
                            ),
                            dim=["HS!", "PVpanel!", "Battery!"],
                        )
                        * coeff_roof_suitability()
                    ).transpose("Type", "District", "PerformanceHigh")
                ).transpose("District", "PerformanceHigh", "Type"),
                lambda: xr.DataArray(
                    0,
                    {
                        "District": _subscript_dict["District"],
                        "PerformanceHigh": _subscript_dict["PerformanceHigh"],
                        "Type": _subscript_dict["Type"],
                    },
                    ["District", "PerformanceHigh", "Type"],
                ),
            ),
            lambda: if_then_else(
                pv_reg_scenario() == 1,
                lambda: if_then_else(
                    time() < 2026,
                    lambda: buildings_construction()
                    .loc[:, :, _subscript_dict["PerformanceHigh"]]
                    .rename({"Performance": "PerformanceHigh"})
                    * coeff_roof_suitability(),
                    lambda: (
                        res_total_construction_by_perf_type_district()
                        .loc[_subscript_dict["PerformanceHigh"], :, :]
                        .rename({"Performance": "PerformanceHigh"})
                        * coeff_roof_suitability()
                    ).transpose("Type", "District", "PerformanceHigh"),
                ),
                lambda: if_then_else(
                    sum(
                        heating_solution()
                        .loc[:, :, _subscript_dict["PerformanceHigh"], :, :, :]
                        .rename(
                            {
                                "HS": "HS!",
                                "Performance": "PerformanceHigh",
                                "PVpanel": "PVpanel!",
                                "Battery": "Battery!",
                            }
                        ),
                        dim=["HS!", "PVpanel!", "Battery!"],
                    )
                    > 0,
                    lambda: (
                        res_total_construction_by_perf_type_district()
                        .loc[_subscript_dict["PerformanceHigh"], :, :]
                        .rename({"Performance": "PerformanceHigh"})
                        * sum(
                            heating_solution()
                            .loc[
                                :, :, _subscript_dict["PerformanceHigh"], :, "PVyes", :
                            ]
                            .reset_coords(drop=True)
                            .rename(
                                {
                                    "HS": "HS!",
                                    "Performance": "PerformanceHigh",
                                    "Battery": "Battery!",
                                }
                            ),
                            dim=["HS!", "Battery!"],
                        ).transpose("PerformanceHigh", "Type", "District")
                        / sum(
                            heating_solution()
                            .loc[:, :, _subscript_dict["PerformanceHigh"], :, :, :]
                            .rename(
                                {
                                    "HS": "HS!",
                                    "Performance": "PerformanceHigh",
                                    "PVpanel": "PVpanel!",
                                    "Battery": "Battery!",
                                }
                            ),
                            dim=["HS!", "PVpanel!", "Battery!"],
                        ).transpose("PerformanceHigh", "Type", "District")
                    ).transpose("District", "PerformanceHigh", "Type"),
                    lambda: xr.DataArray(
                        0,
                        {
                            "District": _subscript_dict["District"],
                            "PerformanceHigh": _subscript_dict["PerformanceHigh"],
                            "Type": _subscript_dict["Type"],
                        },
                        ["District", "PerformanceHigh", "Type"],
                    ),
                ).transpose("Type", "District", "PerformanceHigh"),
            ).transpose("District", "PerformanceHigh", "Type"),
        )
        .expand_dims({"PVpanel": ["PVyes"]}, 3)
        .values
    )


    value.loc[:, _subscript_dict["PerformanceHigh"], :, ["PVno"]] = (
        if_then_else(
            time() < 2026,
            lambda: buildings_construction()
            .loc[:, :, _subscript_dict["PerformanceHigh"]]
            .rename({"Performance": "PerformanceHigh"})
            - value
            .loc[:, _subscript_dict["PerformanceHigh"], :, "PVyes"]
            .reset_coords(drop=True)
            .rename({"Performance": "PerformanceHigh"})
            .transpose("Type", "District", "PerformanceHigh"),
            lambda: (
                res_total_construction_by_perf_type_district()
                .loc[_subscript_dict["PerformanceHigh"], :, :]
                .rename({"Performance": "PerformanceHigh"})
                - value
                .loc[:, _subscript_dict["PerformanceHigh"], :, "PVyes"]
                .reset_coords(drop=True)
                .rename({"Performance": "PerformanceHigh"})
                .transpose("PerformanceHigh", "Type", "District")
            ).transpose("Type", "District", "PerformanceHigh"),
        )
        .transpose("District", "PerformanceHigh", "Type")
        .expand_dims({"PVpanel": ["PVno"]}, 3)
        .values
    )
    return value
