@component.add(
    name="CAPEX retrofit cost",
    units="CHF",
    subscripts=["District", "Type", "Performance"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "low_cost": 1,
        "verylow_cost": 4,
        "moderate_cost": 1,
        "high_cost": 1,
        "veryhigh_cost": 1,
    },
)
def capex_retrofit_cost():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "Type": _subscript_dict["Type"],
            "Performance": _subscript_dict["Performance"],
        },
        ["District", "Type", "Performance"],
    )
    value.loc[:, :, ["VeryLow"]] = 0
    value.loc[:, :, ["Low"]] = (
        (low_cost() - verylow_cost()).expand_dims({"PerformanceLow": ["Low"]}, 2).values
    )
    value.loc[:, :, ["Moderate"]] = (
        (moderate_cost() - verylow_cost())
        .expand_dims({"PerformanceHigh": ["Moderate"]}, 2)
        .values
    )
    value.loc[:, :, ["High"]] = (
        (high_cost() - verylow_cost())
        .expand_dims({"PerformanceHigh": ["High"]}, 2)
        .values
    )
    value.loc[:, :, ["VeryHigh"]] = (
        (veryhigh_cost() - verylow_cost())
        .expand_dims({"PerformanceHigh": ["VeryHigh"]}, 2)
        .values
    )
    return value


