@component.add(
    name="PV CAPEX",
    units="CHF",
    subscripts=["District", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 2,
        "pv_investment_cost": 4,
        "tax_deduction_investment": 4,
        "kwp_installed_per_building": 1,
        "pv_cantonal_subsidy": 2,
        "pv_federal_subsidy_check": 2,
    },
)
def pv_capex():
    return if_then_else(
        time() < 2013,
        lambda: pv_investment_cost() * (1 - tax_deduction_investment()),
        lambda: if_then_else(
            time() < 2016,
            lambda: if_then_else(
                kwp_installed_per_building() < 10,
                lambda: (
                    pv_investment_cost()
                    - pv_cantonal_subsidy()
                    - pv_federal_subsidy_check()
                )
                * (1 - tax_deduction_investment()),
                lambda: pv_investment_cost() * (1 - tax_deduction_investment()),
            ),
            lambda: (
                pv_investment_cost()
                - pv_cantonal_subsidy()
                - pv_federal_subsidy_check()
            )
            * (1 - tax_deduction_investment()),
        ),
    )


@component.add(
    name="Annual electricity cost",
    units="CHF",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "electricity_consumption_by_archetype": 2,
        "total_pv_kwh_sc": 1,
        "electricity_price": 2,
        "annual_subsidy_fit_by_archetype": 1,
    },
)
def annual_electricity_cost():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
            "PVpanel": _subscript_dict["PVpanel"],
        },
        ["District", "HS", "Performance", "Type", "PVpanel"],
    )
    value.loc[:, :, :, :, ["PVyes"]] = (
        (
            (
                electricity_consumption_by_archetype()
                .loc[:, :, :, :, "PVyes"]
                .reset_coords(drop=True)
                - total_pv_kwh_sc()
            )
            * electricity_price()
            - annual_subsidy_fit_by_archetype()
        )
        .expand_dims({"PVpanel": ["PVyes"]}, 4)
        .values
    )
    value.loc[:, :, :, :, ["PVno"]] = (
        (
            electricity_consumption_by_archetype()
            .loc[:, :, :, :, "PVno"]
            .reset_coords(drop=True)
            * electricity_price()
        )
        .expand_dims({"PVpanel": ["PVno"]}, 4)
        .values
    )
    return value


