@component.add(
    name="Incentives by archetype renovation",
    units="CHF",
    subscripts=["Performance", "District", "Type", "HS", "PVpanel"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "verylow_to_performance_sq_m_by_archetype": 3,
        "incentive_base": 2,
        "incentive_cece": 2,
        "incentive_minergie": 2,
        "low_to_performance_sq_m_by_archetype": 3,
    },
)
def incentives_by_archetype_renovation():
    value = xr.DataArray(
        np.nan,
        {
            "Performance": _subscript_dict["Performance"],
            "District": _subscript_dict["District"],
            "Type": _subscript_dict["Type"],
            "HS": _subscript_dict["HS"],
            "PVpanel": _subscript_dict["PVpanel"],
        },
        ["Performance", "District", "Type", "HS", "PVpanel"],
    )
    value.loc[["VeryLow"], :, :, :, :] = (
        (
            verylow_to_performance_sq_m_by_archetype()
            .loc[:, :, "Moderate", :, :]
            .reset_coords(drop=True)
            * incentive_base()
            + verylow_to_performance_sq_m_by_archetype()
            .loc[:, :, "High", :, :]
            .reset_coords(drop=True)
            * incentive_cece()
            + verylow_to_performance_sq_m_by_archetype()
            .loc[:, :, "VeryHigh", :, :]
            .reset_coords(drop=True)
            * incentive_minergie()
        )
        .expand_dims({"PerformanceLow": ["VeryLow"]}, 0)
        .values
    )
    value.loc[["Low"], :, :, :, :] = (
        (
            low_to_performance_sq_m_by_archetype()
            .loc[:, :, "Moderate", :, :]
            .reset_coords(drop=True)
            * incentive_base()
            + low_to_performance_sq_m_by_archetype()
            .loc[:, :, "High", :, :]
            .reset_coords(drop=True)
            * incentive_cece()
            + low_to_performance_sq_m_by_archetype()
            .loc[:, :, "VeryHigh", :, :]
            .reset_coords(drop=True)
            * incentive_minergie()
        )
        .expand_dims({"PerformanceLow": ["Low"]}, 0)
        .values
    )
    value.loc[_subscript_dict["PerformanceHigh"], :, :, :, :] = 0
    return value


