@component.add(
    name="Buildings adopting HS for old age",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel", "Battery"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 2,
        "market_share_hs_no_incentives_filtered": 3,
        "market_share_hs_filtered": 3,
        "consumers_leaving_hs_for_old_age": 9,
    },
)
def buildings_adopting_hs_for_old_age():
    return if_then_else(
        time() < 2016,
        lambda: consumers_leaving_hs_for_old_age()
        .loc[:, "ElectricHeater", :, :, :, :]
        .reset_coords(drop=True)
        * market_share_hs_filtered().transpose(
            "District", "Performance", "Type", "PVpanel", "HS"
        )
        + (
            sum(consumers_leaving_hs_for_old_age().rename({"HS": "HS!"}), dim=["HS!"])
            - consumers_leaving_hs_for_old_age()
            .loc[:, "ElectricHeater", :, :, :, :]
            .reset_coords(drop=True)
        )
        * market_share_hs_no_incentives_filtered().transpose(
            "District", "Performance", "Type", "PVpanel", "HS"
        ),
        lambda: if_then_else(
            time() < 2021,
            lambda: (
                consumers_leaving_hs_for_old_age()
                .loc[:, "ElectricHeater", :, :, :, :]
                .reset_coords(drop=True)
                + consumers_leaving_hs_for_old_age()
                .loc[:, "Oil", :, :, :, :]
                .reset_coords(drop=True)
            )
            * market_share_hs_filtered().transpose(
                "District", "Performance", "Type", "PVpanel", "HS"
            )
            + (
                sum(
                    consumers_leaving_hs_for_old_age()
                    .loc[:, _subscript_dict["NewS"], :, :, :, :]
                    .rename({"HS": "NewS!"}),
                    dim=["NewS!"],
                )
                + consumers_leaving_hs_for_old_age()
                .loc[:, "Gas", :, :, :, :]
                .reset_coords(drop=True)
            )
            * market_share_hs_no_incentives_filtered().transpose(
                "District", "Performance", "Type", "PVpanel", "HS"
            ),
            lambda: sum(
                consumers_leaving_hs_for_old_age()
                .loc[:, _subscript_dict["OldS"], :, :, :, :]
                .rename({"HS": "OldS!"}),
                dim=["OldS!"],
            )
            * market_share_hs_filtered().transpose(
                "District", "Performance", "Type", "PVpanel", "HS"
            )
            + sum(
                consumers_leaving_hs_for_old_age()
                .loc[:, _subscript_dict["NewS"], :, :, :, :]
                .rename({"HS": "NewS!"}),
                dim=["NewS!"],
            )
            * market_share_hs_no_incentives_filtered().transpose(
                "District", "Performance", "Type", "PVpanel", "HS"
            ),
        ),
    ).transpose("District", "HS", "Performance", "Type", "PVpanel", "Battery")


