@component.add(
    name='"Investment grant per kW > 15 kW"',
    units="CHF/kW",
    subscripts=["Tech"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 9},
)
def investment_grant_per_kw_15_kw():
    """
    IF THEN ELSE(Time < 2016.1, 0, IF THEN ELSE(Time < 2021.1, 100, IF THEN ELSE(Time < 2030 , 180 , 180 ) ) )
    """
    value = xr.DataArray(np.nan, {"Tech": _subscript_dict["Tech"]}, ["Tech"])
    value.loc[["OilBoiler"]] = 0
    value.loc[["GasBoiler"]] = 0
    value.loc[["PelletBoiler"]] = if_then_else(
        time() < 2022,
        lambda: 0,
        lambda: if_then_else(
            time() < 2025,
            lambda: 100,
            lambda: if_then_else(time() < 2030, lambda: 360, lambda: 350),
        ),
    )
    value.loc[["HP"]] = if_then_else(
        time() < 2017,
        lambda: 0,
        lambda: if_then_else(
            time() < 2022,
            lambda: 100,
            lambda: if_then_else(time() < 2030, lambda: 180, lambda: 180),
        ),
    )
    value.loc[["EH"]] = 0
    value.loc[["ST"]] = if_then_else(
        time() < 2016.1,
        lambda: 0,
        lambda: if_then_else(
            time() < 2021.1,
            lambda: 200,
            lambda: if_then_else(time() < 2030, lambda: 500, lambda: 0),
        ),
    )
    value.loc[["WoodBoiler"]] = 0
    return value


