@component.add(
    name="Total present variable costs SH Ground",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Stateful",
    comp_subtype="Smooth",
    depends_on={"_smooth_total_present_variable_costs_sh_ground": 1},
    other_deps={
        "_smooth_total_present_variable_costs_sh_ground": {
            "initial": {
                "annual_variable_costs_sh": 1,
                "ground_lifetime": 1,
                "additional_interest_rate_for_loan": 2,
                "interest_rate": 2,
            },
            "step": {
                "annual_variable_costs_sh": 1,
                "ground_lifetime": 1,
                "additional_interest_rate_for_loan": 2,
                "interest_rate": 2,
            },
        }
    },
)
def total_present_variable_costs_sh_ground():
    return _smooth_total_present_variable_costs_sh_ground()


_smooth_total_present_variable_costs_sh_ground = Smooth(
    lambda: annual_variable_costs_sh()
    * (
        1
        - 1
        / (1 + (interest_rate() + additional_interest_rate_for_loan()))
        ** ground_lifetime()
    )
    / (interest_rate() + additional_interest_rate_for_loan()),
    lambda: xr.DataArray(
        5,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
        },
        ["District", "HS", "Performance", "Type"],
    ),
    lambda: annual_variable_costs_sh()
    * (
        1
        - 1
        / (1 + (interest_rate() + additional_interest_rate_for_loan()))
        ** ground_lifetime()
    )
    / (interest_rate() + additional_interest_rate_for_loan()),
    lambda: 1,
    "_smooth_total_present_variable_costs_sh_ground",
)


