@component.add(
    name="Annual SH variable costs HS by archetype",
    units="CHF",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "annual_sh_demand": 17,
        "efficiency": 16,
        "carrier_used_cost_per_kwh": 14,
        "self_sufficiency_degree": 6,
        "pv_cumulative_compensation_price": 3,
    },
)
def annual_sh_variable_costs_hs_by_archetype():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
            "PVpanel": _subscript_dict["PVpanel"],
        },
        ["District", "HS", "Performance", "Type", "PVpanel"],
    )
    value.loc[:, ["OilST"], :, :, :] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["OilBoiler"])
            * carrier_used_cost_per_kwh().loc[:, "OilBoiler"].reset_coords(drop=True)
        )
        .expand_dims({"NonRenSolution": ["OilST"]}, 1)
        .expand_dims({"PVpanel": _subscript_dict["PVpanel"]}, 4)
        .values
    )
    value.loc[:, ["GasST"], :, :, :] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["GasBoiler"])
            * carrier_used_cost_per_kwh().loc[:, "GasBoiler"].reset_coords(drop=True)
        )
        .expand_dims({"WithGeoConstraint": ["GasST"]}, 1)
        .expand_dims({"PVpanel": _subscript_dict["PVpanel"]}, 4)
        .values
    )
    value.loc[:, ["pellet"], :, :, :] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["PelletBoiler"])
            * carrier_used_cost_per_kwh().loc[:, "PelletBoiler"].reset_coords(drop=True)
        )
        .expand_dims({"RenSolution": ["pellet"]}, 1)
        .expand_dims({"PVpanel": _subscript_dict["PVpanel"]}, 4)
        .values
    )
    value.loc[:, ["HeatPump"], :, :, ["PVyes"]] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["HP"])
            * carrier_used_cost_per_kwh().loc[:, "HP"].reset_coords(drop=True)
            * (
                1
                - self_sufficiency_degree()
                .loc[:, "HeatPump", :, :]
                .reset_coords(drop=True)
            )
            - annual_sh_demand()
            / float(efficiency().loc["HP"])
            * pv_cumulative_compensation_price()
            * self_sufficiency_degree().loc[:, "HeatPump", :, :].reset_coords(drop=True)
        )
        .expand_dims({"RenSolution": ["HeatPump"]}, 1)
        .expand_dims({"PVpanel": ["PVyes"]}, 4)
        .values
    )
    value.loc[:, ["WoodST"], :, :, :] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["WoodBoiler"])
            * carrier_used_cost_per_kwh().loc[:, "WoodBoiler"].reset_coords(drop=True)
        )
        .expand_dims({"RenSolution": ["WoodST"]}, 1)
        .expand_dims({"PVpanel": _subscript_dict["PVpanel"]}, 4)
        .values
    )
    value.loc[:, ["HPST"], :, :, ["PVyes"]] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["HP"])
            * carrier_used_cost_per_kwh().loc[:, "HP"].reset_coords(drop=True)
            * (
                1
                - self_sufficiency_degree().loc[:, "HPST", :, :].reset_coords(drop=True)
            )
            - annual_sh_demand()
            / float(efficiency().loc["HP"])
            * pv_cumulative_compensation_price()
            * self_sufficiency_degree().loc[:, "HeatPump", :, :].reset_coords(drop=True)
        )
        .expand_dims({"RenSolution": ["HPST"]}, 1)
        .expand_dims({"PVpanel": ["PVyes"]}, 4)
        .values
    )
    value.loc[:, ["HeatPump"], :, :, ["PVno"]] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["HP"])
            * carrier_used_cost_per_kwh().loc[:, "HP"].reset_coords(drop=True)
        )
        .expand_dims({"RenSolution": ["HeatPump"]}, 1)
        .expand_dims({"PVpanel": ["PVno"]}, 4)
        .values
    )
    value.loc[:, ["HPST"], :, :, ["PVno"]] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["HP"])
            * carrier_used_cost_per_kwh().loc[:, "HP"].reset_coords(drop=True)
        )
        .expand_dims({"RenSolution": ["HPST"]}, 1)
        .expand_dims({"PVpanel": ["PVno"]}, 4)
        .values
    )
    value.loc[:, ["Oil"], :, :, :] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["OilBoiler"])
            * carrier_used_cost_per_kwh().loc[:, "OilBoiler"].reset_coords(drop=True)
        )
        .expand_dims({"NonRenSolution": ["Oil"]}, 1)
        .expand_dims({"PVpanel": _subscript_dict["PVpanel"]}, 4)
        .values
    )
    value.loc[:, ["Gas"], :, :, :] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["GasBoiler"])
            * carrier_used_cost_per_kwh().loc[:, "GasBoiler"].reset_coords(drop=True)
        )
        .expand_dims({"WithGeoConstraint": ["Gas"]}, 1)
        .expand_dims({"PVpanel": _subscript_dict["PVpanel"]}, 4)
        .values
    )
    value.loc[:, ["Wood"], :, :, :] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["WoodBoiler"])
            * carrier_used_cost_per_kwh().loc[:, "WoodBoiler"].reset_coords(drop=True)
        )
        .expand_dims({"RenSolution": ["Wood"]}, 1)
        .expand_dims({"PVpanel": _subscript_dict["PVpanel"]}, 4)
        .values
    )
    value.loc[:, ["ElectricHeater"], :, :, ["PVyes"]] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["EH"])
            * carrier_used_cost_per_kwh().loc[:, "EH"].reset_coords(drop=True)
            * (
                1
                - self_sufficiency_degree()
                .loc[:, "ElectricHeater", :, :]
                .reset_coords(drop=True)
            )
            - annual_sh_demand()
            / float(efficiency().loc["EH"])
            * pv_cumulative_compensation_price()
            * self_sufficiency_degree()
            .loc[:, "ElectricHeater", :, :]
            .reset_coords(drop=True)
        )
        .expand_dims({"NonRenSolution": ["ElectricHeater"]}, 1)
        .expand_dims({"PVpanel": ["PVyes"]}, 4)
        .values
    )
    value.loc[:, ["ElectricHeater"], :, :, ["PVno"]] = (
        (
            -annual_sh_demand()
            / float(efficiency().loc["EH"])
            * carrier_used_cost_per_kwh().loc[:, "EH"].reset_coords(drop=True)
        )
        .expand_dims({"NonRenSolution": ["ElectricHeater"]}, 1)
        .expand_dims({"PVpanel": ["PVno"]}, 4)
        .values
    )
    value.loc[:, ["DH"], :, :, :] = (
        (
            -annual_sh_demand()
            / 1
            * carrier_used_cost_per_kwh().loc[:, "WoodBoiler"].reset_coords(drop=True)
        )
        .expand_dims({"RenSolution": ["DH"]}, 1)
        .expand_dims({"PVpanel": _subscript_dict["PVpanel"]}, 4)
        .values
    )
    return value


