@component.add(
    name="Utility HS exp 2",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 1,
        "utility_hs_exp": 5,
        "muken_2014_scenario": 1,
        "oil_vs_hp_difference": 1,
    },
)
def utility_hs_exp_2():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
            "PVpanel": _subscript_dict["PVpanel"],
        },
        ["District", "HS", "Performance", "Type", "PVpanel"],
    )
    value.loc[:, _subscript_dict["OldS"], _subscript_dict["PerformanceLow"], :, :] = (
        if_then_else(
            time() < 2025,
            lambda: utility_hs_exp()
            .loc[:, _subscript_dict["OldS"], _subscript_dict["PerformanceLow"], :, :]
            .rename({"HS": "OldS", "Performance": "PerformanceLow"}),
            lambda: if_then_else(
                muken_2014_scenario() > 0,
                lambda: if_then_else(
                    (
                        oil_vs_hp_difference()
                        .loc[:, _subscript_dict["PerformanceLow"], :, :]
                        .rename({"Performance": "PerformanceLow"})
                        > 0
                    ).expand_dims({"OldS": _subscript_dict["OldS"]}, 4),
                    lambda: xr.DataArray(
                        0,
                        {
                            "District": _subscript_dict["District"],
                            "PerformanceLow": _subscript_dict["PerformanceLow"],
                            "Type": _subscript_dict["Type"],
                            "PVpanel": _subscript_dict["PVpanel"],
                            "OldS": _subscript_dict["OldS"],
                        },
                        ["District", "PerformanceLow", "Type", "PVpanel", "OldS"],
                    ),
                    lambda: utility_hs_exp()
                    .loc[
                        :,
                        _subscript_dict["OldS"],
                        _subscript_dict["PerformanceLow"],
                        :,
                        :,
                    ]
                    .rename({"HS": "OldS", "Performance": "PerformanceLow"})
                    .transpose("District", "PerformanceLow", "Type", "PVpanel", "OldS"),
                ),
                lambda: utility_hs_exp()
                .loc[
                    :, _subscript_dict["OldS"], _subscript_dict["PerformanceLow"], :, :
                ]
                .rename({"HS": "OldS", "Performance": "PerformanceLow"})
                .transpose("District", "PerformanceLow", "Type", "PVpanel", "OldS"),
            ).transpose("District", "OldS", "PerformanceLow", "Type", "PVpanel"),
        ).values
    )
    value.loc[:, _subscript_dict["NewS"], :, :, :] = (
        utility_hs_exp()
        .loc[:, _subscript_dict["NewS"], :, :, :]
        .rename({"HS": "NewS"})
        .values
    )
    value.loc[:, _subscript_dict["OldS"], _subscript_dict["PerformanceHigh"], :, :] = (
        utility_hs_exp()
        .loc[:, _subscript_dict["OldS"], _subscript_dict["PerformanceHigh"], :, :]
        .rename({"HS": "OldS", "Performance": "PerformanceHigh"})
        .values
    )
    return value


