@component.add(
    name="DH and Gas suitability",
    subscripts=["District", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"dh_suitability": 1, "gas_suitability": 1},
)
def dh_and_gas_suitability():
    return dh_suitability() * gas_suitability()


@component.add(
    name="Gas only suitability",
    subscripts=["District", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"dh_suitability": 1, "gas_suitability": 1},
)
def gas_only_suitability():
    return (1 - dh_suitability()) * gas_suitability()


@component.add(
    name="DH only suitability",
    subscripts=["District", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"dh_suitability": 1, "gas_suitability": 1},
)
def dh_only_suitability():
    return dh_suitability() * (1 - gas_suitability())


@component.add(
    name="Aging Rate",
    subscripts=["HS"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"lifetime": 1},
)
def aging_rate():
    return 1 / lifetime() * 5


@component.add(
    name="Suitability check",
    subscripts=["District", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "dh_and_gas_suitability": 1,
        "dh_only_suitability": 1,
        "gas_only_suitability": 1,
        "no_suitability": 1,
    },
)
def suitability_check():
    return (
        dh_and_gas_suitability()
        + dh_only_suitability()
        + gas_only_suitability()
        + no_suitability()
    )


