@component.add(
    name="Investment grant per kW DH",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 3},
)
def investment_grant_per_kw_dh():
    return if_then_else(
        time() < 2017,
        lambda: 0,
        lambda: if_then_else(
            time() < 2022,
            lambda: 50,
            lambda: if_then_else(time() < 2025, lambda: 50, lambda: 40),
        ),
    )


