@component.add(
    name="Ground Moderate scaled",
    subscripts=["District", "Type", "Performance"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"ground_moderate_scaled": 1, "ground_moderate": 3, "coeff_moderate": 1},
)
def ground_moderate_scaled():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "Type": _subscript_dict["Type"],
            "Performance": _subscript_dict["Performance"],
        },
        ["District", "Type", "Performance"],
    )
    value.loc[:, :, _subscript_dict["PerformanceHigh"]] = (
        (
            ground_moderate()
            .loc[:, :, _subscript_dict["PerformanceHigh"]]
            .rename({"Performance": "PerformanceHigh"})
            - (
                (
                    vmax(
                        ground_moderate().rename({"Performance": "Performance!"}),
                        dim=["Performance!"],
                    )
                    - vmin(
                        ground_moderate().rename({"Performance": "Performance!"}),
                        dim=["Performance!"],
                    )
                )
                / 2
            )
        )
        / 10000
        + coeff_moderate()
        .loc[:, _subscript_dict["PerformanceHigh"]]
        .rename({"Performance": "PerformanceHigh"})
    ).values


    value.loc[:, :, _subscript_dict["PerformanceLow"]] = (
        value
        .loc[:, :, "Moderate"]
        .reset_coords(drop=True)
        .expand_dims({"PerformanceLow": _subscript_dict["PerformanceLow"]}, 2)
        .values
    )
    return value
