@component.add(
    name="HT cumulative cost change",
    subscripts=["Tech"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 5},
)
def ht_cumulative_cost_change():
    value = xr.DataArray(np.nan, {"Tech": _subscript_dict["Tech"]}, ["Tech"])
    value.loc[["OilBoiler"]] = 1
    value.loc[["GasBoiler"]] = 1
    value.loc[["WoodBoiler"]] = 1
    value.loc[["PelletBoiler"]] = 1
    value.loc[["HP"]] = if_then_else(
        time() < 2020,
        lambda: 1.08 - 0.08 * (time() - 2011) / (2020 - 2011),
        lambda: if_then_else(
            time() < 2030,
            lambda: 1 - 0.08 * (time() - 2020) / (2030 - 2020),
            lambda: 0.92 - 0.08 * (time() - 2030) / (2050 - 2030),
        ),
    )
    value.loc[["EH"]] = 1
    value.loc[["ST"]] = 1
    return value


