@component.add(
    name='"PV federal subsidy 30 - 100 kW check"',
    units="CHF",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 1,
        "pv_federal_subsidy_30_100_kw": 1,
        "pv_30_100_kw_investment_cost_time_adj": 2,
        "pv_30_100_kw_share_grant_over_cost": 1,
        "pv_rebate_federal": 1,
    },
)
def pv_federal_subsidy_30_100_kw_check():
    return if_then_else(
        time() < 2026,
        lambda: if_then_else(
            pv_30_100_kw_share_grant_over_cost() < 0.3,
            lambda: pv_federal_subsidy_30_100_kw(),
            lambda: 0.3 * pv_30_100_kw_investment_cost_time_adj(),
        ),
        lambda: pv_rebate_federal() * pv_30_100_kw_investment_cost_time_adj(),
    )


@component.add(
    name='"PV cantonal subsidy 30 - 100 kW check"',
    units="CHF",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 2,
        "pv_federal_subsidy_30_100_kw_check": 3,
        "pv_rebate_cantonal": 1,
        "average_power_pv_30_100_kw": 3,
        "exploratory_analysis": 1,
        "cantonal_pv_support": 1,
        "pv_30_100_kw_investment_cost_time_adj": 2,
    },
)
def pv_cantonal_subsidy_30_100_kw_check():
    return if_then_else(
        time() < 2021,
        lambda: pv_federal_subsidy_30_100_kw_check() / 3,
        lambda: if_then_else(
            time() < 2026,
            lambda: pv_federal_subsidy_30_100_kw_check()
            / 2
            * (average_power_pv_30_100_kw() - 30)
            / average_power_pv_30_100_kw()
            + pv_federal_subsidy_30_100_kw_check()
            / 3
            * 30
            / average_power_pv_30_100_kw(),
            lambda: if_then_else(
                exploratory_analysis() > 0,
                lambda: pv_30_100_kw_investment_cost_time_adj()
                * 0.1
                * cantonal_pv_support(),
                lambda: pv_rebate_cantonal() * pv_30_100_kw_investment_cost_time_adj(),
            ),
        ),
    )


