@component.add(
    name="Annual SH demand by arch",
    units="kWh",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "annual_sh_demand": 1,
        "heating_solution": 1,
        "share_primary_houses": 1,
    },
)
def annual_sh_demand_by_arch():
    return (
        annual_sh_demand()
        * sum(
            heating_solution().rename({"PVpanel": "PVpanel!", "Battery": "Battery!"}),
            dim=["PVpanel!", "Battery!"],
        ).transpose("District", "Performance", "Type", "HS")
        * share_primary_houses()
    ).transpose("District", "HS", "Performance", "Type")


