@component.add(
    name="Annual incentives Cantonal FiT",
    units="Mio CHF",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 1, "total_pv_electricity_injected_in_the_grid": 1, "fit": 1},
)
def annual_incentives_cantonal_fit():
    return if_then_else(
        time() < 2025,
        lambda: 0,
        lambda: total_pv_electricity_injected_in_the_grid() * fit(),
    )


