@component.add(
    name="Average annual Federal Levy cost by Type and PV",
    subscripts=["Type", "PVpanel"],
    comp_type="Stateful",
    comp_subtype="Smooth",
    depends_on={"_smooth_average_annual_federal_levy_cost_by_type_and_pv": 1},
    other_deps={
        "_smooth_average_annual_federal_levy_cost_by_type_and_pv": {
            "initial": {
                "cumulative_cost_federal_levy_by_type_and_pv": 1,
                "total_cumulative_buildings_by_type_and_pv": 1,
            },
            "step": {
                "cumulative_cost_federal_levy_by_type_and_pv": 1,
                "total_cumulative_buildings_by_type_and_pv": 1,
            },
        }
    },
)
def average_annual_federal_levy_cost_by_type_and_pv():
    return _smooth_average_annual_federal_levy_cost_by_type_and_pv()


_smooth_average_annual_federal_levy_cost_by_type_and_pv = Smooth(
    lambda: cumulative_cost_federal_levy_by_type_and_pv()
    / total_cumulative_buildings_by_type_and_pv(),
    lambda: xr.DataArray(
        3,
        {"Type": _subscript_dict["Type"], "PVpanel": _subscript_dict["PVpanel"]},
        ["Type", "PVpanel"],
    ),
    lambda: cumulative_cost_federal_levy_by_type_and_pv()
    / total_cumulative_buildings_by_type_and_pv(),
    lambda: 1,
    "_smooth_average_annual_federal_levy_cost_by_type_and_pv",
)


