@component.add(
    name="Adoption Battery Type",
    subscripts=["Type"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "consumers_adopting_pv_yes_with_battery": 3,
        "consumers_adopting_rcpv_yes_with_battery": 3,
        "buildings_construction_with_battery": 3,
    },
)
def adoption_battery_type():
    value = xr.DataArray(np.nan, {"Type": _subscript_dict["Type"]}, ["Type"])
    value.loc[["SFH"]] = (
        sum(
            consumers_adopting_pv_yes_with_battery()
            .loc[:, :, :, "SFH", "PVyes", "Byes"]
            .reset_coords(drop=True)
            .rename(
                {"District": "District!", "HS": "HS!", "Performance": "Performance!"}
            ),
            dim=["District!", "HS!", "Performance!"],
        )
        + sum(
            consumers_adopting_pv_yes_with_battery()
            .loc[:, :, :, "DFH", "PVyes", "Byes"]
            .reset_coords(drop=True)
            .rename(
                {"District": "District!", "HS": "HS!", "Performance": "Performance!"}
            ),
            dim=["District!", "HS!", "Performance!"],
        )
        + sum(
            consumers_adopting_rcpv_yes_with_battery()
            .loc[:, :, :, "SFH", "PVyes", "Byes"]
            .reset_coords(drop=True)
            .rename(
                {"District": "District!", "HS": "HS!", "Performance": "Performance!"}
            ),
            dim=["District!", "HS!", "Performance!"],
        )
        + sum(
            consumers_adopting_rcpv_yes_with_battery()
            .loc[:, :, :, "DFH", "PVyes", "Byes"]
            .reset_coords(drop=True)
            .rename(
                {"District": "District!", "HS": "HS!", "Performance": "Performance!"}
            ),
            dim=["District!", "HS!", "Performance!"],
        )
        + sum(
            buildings_construction_with_battery()
            .loc[:, :, :, "SFH", "PVyes", "Byes"]
            .reset_coords(drop=True)
            .rename(
                {"District": "District!", "HS": "HS!", "Performance": "Performance!"}
            ),
            dim=["District!", "HS!", "Performance!"],
        )
        + sum(
            buildings_construction_with_battery()
            .loc[:, :, :, "DFH", "PVyes", "Byes"]
            .reset_coords(drop=True)
            .rename(
                {"District": "District!", "HS": "HS!", "Performance": "Performance!"}
            ),
            dim=["District!", "HS!", "Performance!"],
        )
        + 1e-05
    )
    value.loc[["DFH"]] = 0
    value.loc[["MFH"]] = (
        sum(
            consumers_adopting_pv_yes_with_battery()
            .loc[:, :, :, "MFH", "PVyes", "Byes"]
            .reset_coords(drop=True)
            .rename(
                {"District": "District!", "HS": "HS!", "Performance": "Performance!"}
            ),
            dim=["District!", "HS!", "Performance!"],
        )
        + sum(
            consumers_adopting_rcpv_yes_with_battery()
            .loc[:, :, :, "MFH", "PVyes", "Byes"]
            .reset_coords(drop=True)
            .rename(
                {"District": "District!", "HS": "HS!", "Performance": "Performance!"}
            ),
            dim=["District!", "HS!", "Performance!"],
        )
        + sum(
            buildings_construction_with_battery()
            .loc[:, :, :, "DFH", "PVyes", "Byes"]
            .reset_coords(drop=True)
            .rename(
                {"District": "District!", "HS": "HS!", "Performance": "Performance!"}
            ),
            dim=["District!", "HS!", "Performance!"],
        )
        + 1e-05
    )
    return value


