@component.add(
    name="Self consumption degree with Storage RCPv",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "kwh_over_mwh_of_demand_rcpv": 5,
        "self_consumption_degree_rcpv": 2,
        "sc_05_kwhmwh_rcpv": 3,
        "sc_15_kwhmwh_rcpv": 1,
        "sc_10_kwhmwh_rcpv": 3,
    },
)
def self_consumption_degree_with_storage_rcpv():
    return if_then_else(
        kwh_over_mwh_of_demand_rcpv() < 0.5,
        lambda: self_consumption_degree_rcpv()
        + kwh_over_mwh_of_demand_rcpv()
        / 0.5
        * (sc_05_kwhmwh_rcpv() - self_consumption_degree_rcpv()),
        lambda: if_then_else(
            kwh_over_mwh_of_demand_rcpv() < 1,
            lambda: sc_05_kwhmwh_rcpv()
            + (kwh_over_mwh_of_demand_rcpv() - 0.5)
            / 0.5
            * (sc_10_kwhmwh_rcpv() - sc_05_kwhmwh_rcpv()),
            lambda: sc_10_kwhmwh_rcpv()
            + (kwh_over_mwh_of_demand_rcpv() - 1)
            / 0.5
            * (sc_15_kwhmwh_rcpv() - sc_10_kwhmwh_rcpv()),
        ),
    )


