@component.add(name="Battery lifetime", comp_type="Constant", comp_subtype="Normal")
def battery_lifetime():
    return 15


@component.add(
    name="Battery total savings",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "saved_energy_annually": 1,
        "electricity_price": 1,
        "pv_cumulative_compensation_price": 1,
        "battery_lifetime": 1,
        "interest_rate": 2,
    },
)
def battery_total_savings():
    return (
        saved_energy_annually()
        * (electricity_price() - pv_cumulative_compensation_price())
        * (1 - 1 / (1 + interest_rate()) ** battery_lifetime())
        / interest_rate()
    )


