@component.add(
    name="Self consumption degree with Storage",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "kwh_over_mwh_of_demand": 5,
        "sc_05_kwhmwh": 3,
        "self_consumption_degree": 2,
        "sc_10_kwhmwh": 3,
        "sc_15_kwhmwh": 1,
    },
)
def self_consumption_degree_with_storage():
    return if_then_else(
        kwh_over_mwh_of_demand() < 0.5,
        lambda: self_consumption_degree()
        + kwh_over_mwh_of_demand() / 0.5 * (sc_05_kwhmwh() - self_consumption_degree()),
        lambda: if_then_else(
            kwh_over_mwh_of_demand() < 1,
            lambda: sc_05_kwhmwh()
            + (kwh_over_mwh_of_demand() - 0.5)
            / 0.5
            * (sc_10_kwhmwh() - sc_05_kwhmwh()),
            lambda: sc_10_kwhmwh()
            + (kwh_over_mwh_of_demand() - 1) / 0.5 * (sc_15_kwhmwh() - sc_10_kwhmwh()),
        ),
    )


