@component.add(
    name="Probability adoption battery",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 1, "utility_battery_exp": 2},
)
def probability_adoption_battery():
    return if_then_else(
        time() < 2016,
        lambda: xr.DataArray(
            0,
            {
                "District": _subscript_dict["District"],
                "HS": _subscript_dict["HS"],
                "Performance": _subscript_dict["Performance"],
                "Type": _subscript_dict["Type"],
            },
            ["District", "HS", "Performance", "Type"],
        ),
        lambda: utility_battery_exp() / (1 + utility_battery_exp()),
    )


