@component.add(
    name="Owners adopting PV flow",
    subscripts=["District", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "owned_buildings_with_pv": 3,
        "owners_adopting_pv": 2,
        "building_construction_by_archetype": 1,
        "owned_buildings_with_rcp": 1,
        "share_of_owned_houses": 1,
        "owned_buildings_with_rcpv": 1,
    },
)
def owners_adopting_pv_flow():
    return np.maximum(
        if_then_else(
            owned_buildings_with_pv() > 0,
            lambda: sum(
                owners_adopting_pv().rename(
                    {"HS": "HS!", "Performance": "Performance!"}
                ),
                dim=["HS!", "Performance!"],
            )
            + sum(
                building_construction_by_archetype()
                .loc[:, :, :, "PVyes"]
                .reset_coords(drop=True)
                .rename({"Performance": "Performance!"}),
                dim=["Performance!"],
            )
            * share_of_owned_houses()
            * owned_buildings_with_pv()
            / (
                owned_buildings_with_pv()
                + owned_buildings_with_rcp()
                + owned_buildings_with_rcpv()
            ),
            lambda: sum(
                owners_adopting_pv().rename(
                    {"HS": "HS!", "Performance": "Performance!"}
                ),
                dim=["HS!", "Performance!"],
            ),
        ),
        0,
    )


