@component.add(
    name="Annual charging station power installed",
    units="kW",
    subscripts=["District"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "consumers_acquiring_vehicle": 3,
        "ev_private_charging_station_power": 1,
        "phev_private_charging_station_power": 1,
        "public_charging_stations_installations_per_district": 1,
    },
)
def annual_charging_station_power_installed():
    return (
        consumers_acquiring_vehicle().loc[:, "BEV"].reset_coords(drop=True)
        * ev_private_charging_station_power()
        + (
            consumers_acquiring_vehicle().loc[:, "DieselPHEV"].reset_coords(drop=True)
            + consumers_acquiring_vehicle().loc[:, "PetrolPHEV"].reset_coords(drop=True)
        )
        * phev_private_charging_station_power()
        + public_charging_stations_installations_per_district() * 22
    )


@component.add(
    name="Public charging stations installations per District",
    subscripts=["District"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "consumers_acquiring_vehicle": 3,
        "ev_share_distribution_in_districts": 1,
    },
)
def public_charging_stations_installations_per_district():
    return (
        (
            sum(
                consumers_acquiring_vehicle()
                .loc[:, "BEV"]
                .reset_coords(drop=True)
                .rename({"District": "District!"}),
                dim=["District!"],
            )
            + (
                sum(
                    consumers_acquiring_vehicle()
                    .loc[:, "DieselPHEV"]
                    .reset_coords(drop=True)
                    .rename({"District": "District!"}),
                    dim=["District!"],
                )
                + sum(
                    consumers_acquiring_vehicle()
                    .loc[:, "PetrolPHEV"]
                    .reset_coords(drop=True)
                    .rename({"District": "District!"}),
                    dim=["District!"],
                )
            )
            * 0.08
        )
        / 9
        * ev_share_distribution_in_districts()
    )


