@component.add(
    name="PHS hourly supply",
    subscripts=["Month", "Hour"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "hourly_phs_production": 1,
        "phs_hourly_increase": 1,
        "phs_hourly_decrease": 1,
        "seasonal_phs_hourly_production": 1,
    },
)
def phs_hourly_supply():
    """
    IF THEN ELSE( Hourly PHS production[Month,Hour] + PHS hourly increase[Month,Hour] - PHS hourly decrease[Month,Hour] > 0.0016 , Hourly PHS production[Month,Hour] + PHS hourly increase[Month,Hour] - PHS hourly decrease[Month,Hour] , 0.0016 )
    """
    return (
        hourly_phs_production()
        + phs_hourly_increase()
        - phs_hourly_decrease()
        + seasonal_phs_hourly_production()
    )


