@component.add(
    name="PHS hourly decrease",
    subscripts=["Month", "Hour"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "pv_hourly_difference": 3,
        "hourly_phs_production": 3,
        "pv_hourly_supply": 1,
        "hourly_total_inflow_for_ticino": 1,
        "wind_hourly_supply": 1,
        "share_phs": 2,
        "rr_hourly_supply": 1,
        "hourly_electricity_grid_demand": 1,
        "waste_hourly_supply": 1,
    },
)
def phs_hourly_decrease():
    """
    IF THEN ELSE( PV hourly difference[Month,Hour] > 0 , IF THEN ELSE( ( PV hourly supply[Month,Hour] + RR hourly supply[Month,Hour] ) > Hourly electricity demand[Month,Hour] , Hourly PHS production[Month,Hour] , IF THEN ELSE( ( PV hourly supply[Month,Hour] + RR hourly supply[Month,Hour] + Hourly total inflow for Ticino[Month,Hour] + Hourly PHS production[Month,Hour] ) > Hourly electricity demand[Month,Hour] , ( PV hourly supply[Month,Hour] + RR hourly supply[Month,Hour] + Hourly total inflow for Ticino[Month,Hour] + Hourly PHS production[Month,Hour] - Hourly electricity demand[Month,Hour] ) * Share PHS[Month,Hour] , 0 )) , 0 )
    """
    return if_then_else(
        pv_hourly_difference() > 0,
        lambda: if_then_else(
            pv_hourly_difference() * share_phs() > hourly_phs_production(),
            lambda: hourly_phs_production(),
            lambda: if_then_else(
                pv_hourly_supply()
                + rr_hourly_supply()
                + wind_hourly_supply()
                + waste_hourly_supply()
                + hourly_total_inflow_for_ticino()
                + hourly_phs_production()
                > hourly_electricity_grid_demand(),
                lambda: pv_hourly_difference() * share_phs(),
                lambda: xr.DataArray(
                    0,
                    {
                        "Month": _subscript_dict["Month"],
                        "Hour": _subscript_dict["Hour"],
                    },
                    ["Month", "Hour"],
                ),
            ),
        ),
        lambda: xr.DataArray(
            0,
            {"Month": _subscript_dict["Month"], "Hour": _subscript_dict["Hour"]},
            ["Month", "Hour"],
        ),
    )


@component.add(
    name="Waste hourly supply",
    subscripts=["Month", "Hour"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"waste_annual_production": 12},
)
def waste_hourly_supply():
    value = xr.DataArray(
        np.nan,
        {"Month": _subscript_dict["Month"], "Hour": _subscript_dict["Hour"]},
        ["Month", "Hour"],
    )
    value.loc[["M1"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12)
    value.loc[["M2"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12)
    value.loc[["M3"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12)
    value.loc[["M4"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12)
    value.loc[["M5"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12) * 0.5
    value.loc[["M6"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12) * 0.5
    value.loc[["M7"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12) * 0.6
    value.loc[["M8"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12)
    value.loc[["M9"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12)
    value.loc[["M10"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12)
    value.loc[["M11"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12)
    value.loc[["M12"], :] = waste_annual_production() / 10.6 / 24 / (365 / 12)
    return value


