def hourly_available_supply_by_supplier():
    value = xr.DataArray(
        np.nan,
        {
            "Month": _subscript_dict["Month"],
            "Hour": _subscript_dict["Hour"],
            "Supplier": _subscript_dict["Supplier"],
        },
        ["Month", "Hour", "Supplier"],
    )
    value.loc[:, :, ["Solar"]] = (
        pv_hourly_supply().expand_dims({"Supplier": ["Solar"]}, 2).values
    )
    value.loc[:, :, ["Wind"]] = (
        wind_hourly_supply().expand_dims({"Supplier": ["Wind"]}, 2).values
    )
    value.loc[:, :, ["Nuclear"]] = (
        nuclear_hourly_available_supply()
        .expand_dims({"Supplier": ["Nuclear"]}, 2)
        .values
    )
    value.loc[:, :, ["RoR"]] = (
        rr_hourly_supply().expand_dims({"Supplier": ["RoR"]}, 2).values
    )
    value.loc[:, :, ["Hydro"]] = (
        hydro_hourly_available_supply_for_ticino()
        .expand_dims({"Supplier": ["Hydro"]}, 2)
        .values
    )
    value.loc[:, :, ["Import"]] = import_hourly_available_supply()
    value.loc[:, :, ["PHS"]] = (
        phs_hourly_supply().expand_dims({"Supplier": ["PHS"]}, 2).values
    )
    value.loc[:, :, ["Coal"]] = (
        coal_hourly_available_supply().expand_dims({"Supplier": ["Coal"]}, 2).values
    )
    value.loc[:, :, ["Waste"]] = (
        waste_hourly_supply().expand_dims({"Supplier": ["Waste"]}, 2).values
    )
    return value


@component.add(
    name="HS hourly decrease",
    subscripts=["Month", "Hour"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "pv_hourly_difference": 3,
        "hourly_phs_production": 1,
        "pv_hourly_supply": 1,
        "hourly_total_inflow_for_ticino": 3,
        "wind_hourly_supply": 1,
        "rr_hourly_supply": 1,
        "hourly_electricity_grid_demand": 1,
        "share_hs": 2,
        "waste_hourly_supply": 1,
    },
)
def hs_hourly_decrease():
    """
    IF THEN ELSE( PV hourly difference[Month,Hour] > 0 , IF THEN ELSE( ( PV hourly supply[Month,Hour] + RR hourly supply[Month,Hour] + Wind hourly supply[Month,Hour] + Waste hourly supply[Month,Hour] ) > Hourly electricity grid demand[Month,Hour] , Hourly total inflow for Ticino[Month,Hour] , IF THEN ELSE( ( PV hourly supply[Month,Hour] + RR hourly supply[Month,Hour] + Wind hourly supply[Month,Hour] + Waste hourly supply[Month,Hour] + Hourly total inflow for Ticino[Month,Hour] + Hourly PHS production[Month,Hour] ) > Hourly electricity grid demand[Month,Hour] , ( PV hourly difference[Month,Hour] ) * Share HS[Month,Hour] , 0 ) ) , 0 )
    """
    return if_then_else(
        pv_hourly_difference() > 0,
        lambda: if_then_else(
            pv_hourly_difference() * share_hs() > hourly_total_inflow_for_ticino(),
            lambda: hourly_total_inflow_for_ticino(),
            lambda: if_then_else(
                pv_hourly_supply()
                + rr_hourly_supply()
                + wind_hourly_supply()
                + waste_hourly_supply()
                + hourly_total_inflow_for_ticino()
                + hourly_phs_production()
                > hourly_electricity_grid_demand(),
                lambda: pv_hourly_difference() * share_hs(),
                lambda: xr.DataArray(
                    0,
                    {
                        "Month": _subscript_dict["Month"],
                        "Hour": _subscript_dict["Hour"],
                    },
                    ["Month", "Hour"],
                ),
            ),
        ),
        lambda: xr.DataArray(
            0,
            {"Month": _subscript_dict["Month"], "Hour": _subscript_dict["Hour"]},
            ["Month", "Hour"],
        ),
    )


