@component.add(
    name="Annual total inflow for Ticino",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "annual_hs_inflow_for_ticino": 1,
        "annual_phsn_inflow_for_ticino": 1,
        "time": 8,
        "deflussi_minimi_lpac": 1,
        "cambiamento_climatico_hydro": 1,
        "provvedimento_12": 1,
        "provvedimento_13": 1,
    },
)
def annual_total_inflow_for_ticino():
    return (
        (annual_hs_inflow_for_ticino() + annual_phsn_inflow_for_ticino()) / 1000
        - if_then_else(
            time() < 2026,
            lambda: 0,
            lambda: deflussi_minimi_lpac() * 305 * (time() - 2026) / (2050 - 2026),
        )
        - if_then_else(
            time() < 2026,
            lambda: 0,
            lambda: cambiamento_climatico_hydro()
            * 225
            * (time() - 2026)
            / (2050 - 2026),
        )
        + if_then_else(
            time() < 2026,
            lambda: 0,
            lambda: provvedimento_12() * 214 * (time() - 2026) / (2050 - 2026),
        )
        + if_then_else(
            time() < 2026,
            lambda: 0,
            lambda: provvedimento_13() * 293 * (time() - 2026) / (2050 - 2026),
        )
    )


