def coal_hourly_available_supply():
    return coal_hourly_available_supply_historical() * time_factor_coal() * 0.75


@component.add(
    name="Coal hourly available supply historical",
    units="GWh",
    subscripts=["Month", "Hour"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"coal_annual_import": 12},
)
def coal_hourly_available_supply_historical():
    value = xr.DataArray(
        np.nan,
        {"Month": _subscript_dict["Month"], "Hour": _subscript_dict["Hour"]},
        ["Month", "Hour"],
    )
    value.loc[["M1"], :] = coal_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M2"], :] = coal_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M3"], :] = coal_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M4"], :] = coal_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M5"], :] = coal_annual_import() * 0.5 / 10.6 / 24 / (365 / 12)
    value.loc[["M6"], :] = coal_annual_import() * 0.5 / 10.6 / 24 / (365 / 12)
    value.loc[["M7"], :] = coal_annual_import() * 0.6 / 10.6 / 24 / (365 / 12)
    value.loc[["M8"], :] = coal_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M9"], :] = coal_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M10"], :] = coal_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M11"], :] = coal_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M12"], :] = coal_annual_import() / 10.6 / 24 / (365 / 12)
    return value


