@component.add(
    name="Hour factor PHS consumption",
    subscripts=["Month", "Hour"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "phs_hourly_supply_2023_inverse_scaled": 1,
        "hour_factor_phs_consumption_new_tot": 1,
    },
)
def hour_factor_phs_consumption():
    return (
        phs_hourly_supply_2023_inverse_scaled()
        / hour_factor_phs_consumption_new_tot()
        / (365 / 12)
    )


@component.add(
    name="Hour factor PHS consumption new TOT",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"phs_hourly_supply_2023_inverse_scaled": 1},
)
def hour_factor_phs_consumption_new_tot():
    return sum(
        phs_hourly_supply_2023_inverse_scaled().rename(
            {"Month": "Month!", "Hour": "Hour!"}
        ),
        dim=["Month!", "Hour!"],
    )


