@component.add(
    name="Nuclear hourly available supply historical",
    units="GWh",
    subscripts=["Month", "Hour"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"nuclear_annual_import": 12},
)
def nuclear_hourly_available_supply_historical():
    value = xr.DataArray(
        np.nan,
        {"Month": _subscript_dict["Month"], "Hour": _subscript_dict["Hour"]},
        ["Month", "Hour"],
    )
    value.loc[["M1"], :] = nuclear_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M2"], :] = nuclear_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M3"], :] = nuclear_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M4"], :] = nuclear_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M5"], :] = nuclear_annual_import() * 0.5 / 10.6 / 24 / (365 / 12)
    value.loc[["M6"], :] = nuclear_annual_import() * 0.5 / 10.6 / 24 / (365 / 12)
    value.loc[["M7"], :] = nuclear_annual_import() * 0.6 / 10.6 / 24 / (365 / 12)
    value.loc[["M8"], :] = nuclear_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M9"], :] = nuclear_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M10"], :] = nuclear_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M11"], :] = nuclear_annual_import() / 10.6 / 24 / (365 / 12)
    value.loc[["M12"], :] = nuclear_annual_import() / 10.6 / 24 / (365 / 12)
    return value


