@component.add(
    name="Utility HS exp",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"utility_hs": 4, "time": 1},
)
def utility_hs_exp():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
            "PVpanel": _subscript_dict["PVpanel"],
        },
        ["District", "HS", "Performance", "Type", "PVpanel"],
    )
    value.loc[:, _subscript_dict["NewS"], :, :, :] = np.exp(
        utility_hs().loc[:, _subscript_dict["NewS"], :, :, :].rename({"HS": "NewS"})
    ).values
    value.loc[:, ["Oil"], :, :, :] = (
        np.exp(utility_hs().loc[:, "Oil", :, :, :].reset_coords(drop=True))
        .expand_dims({"NonRenSolution": ["Oil"]}, 1)
        .values
    )
    value.loc[:, ["Gas"], :, :, :] = (
        np.exp(utility_hs().loc[:, "Gas", :, :, :].reset_coords(drop=True))
        .expand_dims({"WithGeoConstraint": ["Gas"]}, 1)
        .values
    )
    value.loc[:, ["ElectricHeater"], :, :, :] = (
        if_then_else(
            time() < 2018,
            lambda: np.exp(
                utility_hs().loc[:, "ElectricHeater", :, :, :].reset_coords(drop=True)
            ),
            lambda: xr.DataArray(
                0,
                {
                    "District": _subscript_dict["District"],
                    "Performance": _subscript_dict["Performance"],
                    "Type": _subscript_dict["Type"],
                    "PVpanel": _subscript_dict["PVpanel"],
                },
                ["District", "Performance", "Type", "PVpanel"],
            ),
        )
        .expand_dims({"NonRenSolution": ["ElectricHeater"]}, 1)
        .values
    )
    return value


