@component.add(
    name="Annual HP kW installation by archetype",
    units="kW",
    subscripts=["District", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "buildings_adopting_hs": 2,
        "buildings_hs_renovation_to": 2,
        "consumers_adopting_pv_yes": 2,
        "consumers_leaving_hs_for_old_age": 2,
        "technology_sh_installed_capacity_sh_and_dhw": 1,
        "technology_dhw_installed_capacity_sh_and_dhw": 1,
        "technology_sh_installed_capacity_just_sh": 1,
    },
)
def annual_hp_kw_installation_by_archetype():
    return (
        sum(
            buildings_adopting_hs()
            .loc[:, "HeatPump", :, :, :, :]
            .reset_coords(drop=True)
            .rename({"Battery": "Battery!"}),
            dim=["Battery!"],
        )
        - sum(
            buildings_hs_renovation_to()
            .loc[:, "HeatPump", :, :, :, :]
            .reset_coords(drop=True)
            .rename({"Battery": "Battery!"}),
            dim=["Battery!"],
        )
        - consumers_adopting_pv_yes()
        .loc[:, "HeatPump", :, :, :]
        .reset_coords(drop=True)
        - sum(
            consumers_leaving_hs_for_old_age()
            .loc[:, "HeatPump", :, :, :, :]
            .reset_coords(drop=True)
            .rename({"Battery": "Battery!"}),
            dim=["Battery!"],
        )
    ) * (
        technology_sh_installed_capacity_sh_and_dhw()
        + technology_dhw_installed_capacity_sh_and_dhw()
    ) + (
        sum(
            buildings_adopting_hs()
            .loc[:, "HPST", :, :, :, :]
            .reset_coords(drop=True)
            .rename({"Battery": "Battery!"}),
            dim=["Battery!"],
        )
        - sum(
            buildings_hs_renovation_to()
            .loc[:, "HPST", :, :, :, :]
            .reset_coords(drop=True)
            .rename({"Battery": "Battery!"}),
            dim=["Battery!"],
        )
        - consumers_adopting_pv_yes().loc[:, "HPST", :, :, :].reset_coords(drop=True)
        - sum(
            consumers_leaving_hs_for_old_age()
            .loc[:, "HPST", :, :, :, :]
            .reset_coords(drop=True)
            .rename({"Battery": "Battery!"}),
            dim=["Battery!"],
        )
    ) * technology_sh_installed_capacity_just_sh()


