@component.add(
    name="Share HS by archetype",
    units="Dmnl",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel", "Battery"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"heating_solution": 2},
)
def share_hs_by_archetype():
    return heating_solution() / sum(
        heating_solution().rename(
            {"HS": "HS!", "PVpanel": "PVpanel!", "Battery": "Battery!"}
        ),
        dim=["HS!", "PVpanel!", "Battery!"],
    )


