@component.add(
    name="Initial kWp installed by archetype",
    units="kW",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"initial_heating_solution": 1, "kwp_installed_per_building": 1},
)
def initial_kwp_installed_by_archetype():
    return (
        initial_heating_solution().loc[:, :, :, :, "PVyes"].reset_coords(drop=True)
        * kwp_installed_per_building()
    )


@component.add(
    name="Annual PV kW installation by archetype",
    units="kW",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "pv_adoptions_by_archetype": 1,
        "kwp_installed_per_building": 1,
        "rcpv_adoptions_by_archetype": 1,
        "kwp_installed_per_building_rcpv": 1,
    },
)
def annual_pv_kw_installation_by_archetype():
    return (
        sum(
            pv_adoptions_by_archetype().rename({"Battery": "Battery!"}),
            dim=["Battery!"],
        )
        * kwp_installed_per_building()
        + sum(
            rcpv_adoptions_by_archetype().rename({"Battery": "Battery!"}),
            dim=["Battery!"],
        )
        * kwp_installed_per_building_rcpv()
    )


@component.add(
    name="kWp installed per building RCPv",
    units="kW",
    subscripts=["District", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"kwp_installed_per_building": 1, "share_additional_power_rcpv": 1},
)
def kwp_installed_per_building_rcpv():
    return kwp_installed_per_building() * (1 + share_additional_power_rcpv())


@component.add(
    name="kWp installed per building",
    units="kW",
    subscripts=["District", "Type"],
    comp_type="Constant",
    comp_subtype="Normal",
)
def kwp_installed_per_building():
    return xr.DataArray(
        [
            [11.11, 12.35, 21.03],
            [10.8, 12.05, 14.63],
            [11.6, 11.46, 13.55],
            [12.11, 11.53, 19.67],
            [10.59, 12.02, 19.63],
            [11.32, 14.3, 20.45],
            [12.66, 15.34, 16.4],
            [10.54, 11.62, 13.86],
        ],
        {"District": _subscript_dict["District"], "Type": _subscript_dict["Type"]},
        ["District", "Type"],
    )


@component.add(
    name="PV annual generation per kW",
    units="kWh/kW",
    comp_type="Constant",
    comp_subtype="Normal",
)
def pv_annual_generation_per_kw():
    return 1128.26


@component.add(
    name="House Value coefficient HT",
    units="Dmnl",
    subscripts=["Performance", "HS"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={"house_value_coefficient": 1},
)
def house_value_coefficient_ht():
    value = xr.DataArray(
        np.nan,
        {"Performance": _subscript_dict["Performance"], "HS": _subscript_dict["HS"]},
        ["Performance", "HS"],
    )
    except_subs = xr.ones_like(value, dtype=bool)
    except_subs.loc[:, _subscript_dict["HPs"]] = False
    value.values[except_subs.values] = 0.1295
    value.loc[:, _subscript_dict["HPs"]] = (
        house_value_coefficient().expand_dims({"HPs": _subscript_dict["HPs"]}, 1).values
    )
    return value


