@component.add(
    name="Total Res buildings",
    subscripts=["District", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "res_verylow_buildings": 1,
        "res_low_buildings": 1,
        "res_moderate_buildings": 1,
        "res_high_buildings": 1,
        "res_veryhigh_buildings": 1,
    },
)
def total_res_buildings():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
        },
        ["District", "Performance", "Type"],
    )
    value.loc[:, ["VeryLow"], :] = (
        res_verylow_buildings().expand_dims({"PerformanceLow": ["VeryLow"]}, 1).values
    )
    value.loc[:, ["Low"], :] = (
        res_low_buildings().expand_dims({"PerformanceLow": ["Low"]}, 1).values
    )
    value.loc[:, ["Moderate"], :] = (
        res_moderate_buildings()
        .expand_dims({"PerformanceHigh": ["Moderate"]}, 1)
        .values
    )
    value.loc[:, ["High"], :] = (
        res_high_buildings().expand_dims({"PerformanceHigh": ["High"]}, 1).values
    )
    value.loc[:, ["VeryHigh"], :] = (
        res_veryhigh_buildings()
        .expand_dims({"PerformanceHigh": ["VeryHigh"]}, 1)
        .values
    )
    return value


