@component.add(
    name="House Value Utility PV factor",
    units="Dmnl",
    subscripts=["Performance"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"house_value_coefficient": 3, "house_value_utility_pv_weight": 1},
)
def house_value_utility_pv_factor():
    return (
        house_value_coefficient()
        - (
            vmax(
                house_value_coefficient().rename({"Performance": "Performance!"}),
                dim=["Performance!"],
            )
            + vmin(
                house_value_coefficient().rename({"Performance": "Performance!"}),
                dim=["Performance!"],
            )
        )
        / 2
    ) * house_value_utility_pv_weight()


