@component.add(
    name="Cost per km el",
    units="CHF/km",
    subscripts=["District", "Vechicle"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "el_consumption_per_km": 3,
        "electricity_price": 3,
        "share_of_electricity_bought_from_public": 3,
        "share_of_buildings_with_pv": 2,
    },
)
def cost_per_km_el():
    return (
        el_consumption_per_km()
        * electricity_price()
        * (1 - share_of_electricity_bought_from_public())
        * (1 - share_of_buildings_with_pv())
        + el_consumption_per_km()
        * electricity_price()
        * (1 - share_of_electricity_bought_from_public())
        * 0.65
        * share_of_buildings_with_pv()
        + el_consumption_per_km()
        * electricity_price()
        * 3
        * share_of_electricity_bought_from_public()
    ).transpose("District", "Vechicle")


