@component.add(
    name="Economic Utility V",
    subscripts=["District", "Vechicle"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"total_annualised_cost_vehicle": 4},
)
def economic_utility_v():
    """
    ( Total annualised cost vehicle[District,Vechicle] - ( VMAX(Total annualised cost vehicle[District,Vechicle!]) + VMIN(Total annualised cost vehicle[District,Vechicle!]) ) / 2 ) / VMAX(Total annualised cost vehicle[District,Vechicle!])
    """
    return (
        total_annualised_cost_vehicle()
        - (
            (
                vmax(
                    total_annualised_cost_vehicle().rename({"Vechicle": "Vechicle!"}),
                    dim=["Vechicle!"],
                )
                + vmin(
                    total_annualised_cost_vehicle().rename({"Vechicle": "Vechicle!"}),
                    dim=["Vechicle!"],
                )
            )
            / 2
        )
    ) / vmax(
        total_annualised_cost_vehicle().rename({"Vechicle": "Vechicle!"}),
        dim=["Vechicle!"],
    )


