@component.add(
    name="CO2eq per km",
    units="CO2eq/km",
    subscripts=["Vechicle"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "fuel_consumption_per_km": 6,
        "emissions_per_mwh_petrol": 3,
        "emissions_per_mwh_diesel": 3,
        "emissions_per_kwh_carrier_used": 3,
        "el_consumption_per_km": 3,
    },
)
def co2eq_per_km():
    value = xr.DataArray(
        np.nan, {"Vechicle": _subscript_dict["Vechicle"]}, ["Vechicle"]
    )
    value.loc[["Petrol"]] = (
        float(fuel_consumption_per_km().loc["Petrol"])
        * emissions_per_mwh_petrol()
        / 1000
        / 3600
    )
    value.loc[["Diesel"]] = (
        float(fuel_consumption_per_km().loc["Diesel"])
        * emissions_per_mwh_diesel()
        / 1000
        / 3600
    )
    value.loc[["PetrolHEV"]] = (
        float(fuel_consumption_per_km().loc["PetrolHEV"])
        * emissions_per_mwh_petrol()
        / 1000
        / 3600
    )
    value.loc[["PetrolPHEV"]] = float(
        fuel_consumption_per_km().loc["PetrolPHEV"]
    ) * emissions_per_mwh_petrol() / 1000 / 3600 + float(
        emissions_per_kwh_carrier_used().loc["HP"]
    ) * float(
        el_consumption_per_km().loc["PetrolPHEV"]
    )
    value.loc[["DieselHEV"]] = (
        float(fuel_consumption_per_km().loc["DieselHEV"])
        * emissions_per_mwh_diesel()
        / 1000
        / 3600
    )
    value.loc[["DieselPHEV"]] = float(
        fuel_consumption_per_km().loc["DieselPHEV"]
    ) * emissions_per_mwh_diesel() / 1000 / 3600 + float(
        emissions_per_kwh_carrier_used().loc["HP"]
    ) * float(
        el_consumption_per_km().loc["DieselPHEV"]
    )
    value.loc[["BEV"]] = float(el_consumption_per_km().loc["BEV"]) * float(
        emissions_per_kwh_carrier_used().loc["HP"]
    )
    return value


