@component.add(
    name="Infrastructure Utility",
    subscripts=["Vechicle"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={"public_charging_stations": 9},
)
def infrastructure_utility():
    value = xr.DataArray(
        np.nan, {"Vechicle": _subscript_dict["Vechicle"]}, ["Vechicle"]
    )
    value.loc[_subscript_dict["ICE"]] = 1
    value.loc[["PetrolHEV"]] = 1
    value.loc[["PetrolPHEV"]] = (
        if_then_else(
            public_charging_stations() < 1000,
            lambda: float(np.exp(public_charging_stations() / 100))
            / (
                float(np.exp(public_charging_stations() / 100))
                + float(np.exp(300 / 100))
            ),
            lambda: 1,
        )
        * 0.5
        + 0.5
    )
    value.loc[["DieselHEV"]] = 1
    value.loc[["DieselPHEV"]] = (
        if_then_else(
            public_charging_stations() < 1000,
            lambda: float(np.exp(public_charging_stations() / 100))
            / (
                float(np.exp(public_charging_stations() / 100))
                + float(np.exp(300 / 100))
            ),
            lambda: 1,
        )
        * 0.5
        + 0.5
    )
    value.loc[["BEV"]] = if_then_else(
        public_charging_stations() < 1000,
        lambda: float(np.exp(public_charging_stations() / 100))
        / (float(np.exp(public_charging_stations() / 100)) + float(np.exp(300 / 100))),
        lambda: 1,
    )
    return value


