@component.add(
    name="Cost per km fuel",
    units="CHF/km",
    subscripts=["Vechicle"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "fuel_consumption_per_km": 6,
        "petrol_price": 3,
        "density_petrol": 3,
        "lhv_petrol": 3,
        "lhv_diesel": 3,
        "diesel_price": 3,
        "denity_diesel": 3,
    },
)
def cost_per_km_fuel():
    value = xr.DataArray(
        np.nan, {"Vechicle": _subscript_dict["Vechicle"]}, ["Vechicle"]
    )
    value.loc[["Petrol"]] = (
        float(fuel_consumption_per_km().loc["Petrol"])
        * petrol_price()
        / (1000 * lhv_petrol() * density_petrol())
    )
    value.loc[["Diesel"]] = (
        float(fuel_consumption_per_km().loc["Diesel"])
        * diesel_price()
        / (1000 * lhv_diesel() * denity_diesel())
    )
    value.loc[["PetrolHEV"]] = (
        float(fuel_consumption_per_km().loc["PetrolHEV"])
        * petrol_price()
        / (1000 * lhv_petrol() * density_petrol())
    )
    value.loc[["PetrolPHEV"]] = (
        float(fuel_consumption_per_km().loc["PetrolPHEV"])
        * petrol_price()
        / (1000 * lhv_petrol() * density_petrol())
    )
    value.loc[["DieselHEV"]] = (
        float(fuel_consumption_per_km().loc["DieselHEV"])
        * diesel_price()
        / (1000 * lhv_diesel() * denity_diesel())
    )
    value.loc[["DieselPHEV"]] = (
        float(fuel_consumption_per_km().loc["DieselPHEV"])
        * diesel_price()
        / (1000 * lhv_diesel() * denity_diesel())
    )
    value.loc[["BEV"]] = 0
    return value


