@component.add(
    name="PV cumulative compensation price",
    units="Dmnl",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 11,
        "fit": 1,
        "cantonal_pv_support": 1,
        "pv_uncertain_remunaration_factor": 1,
    },
)
def pv_cumulative_compensation_price():
    """
    0.0955 0.0835 0.0754 0.0673 0.0704 0.0721 0.0656 0.0754 0.1288 0.1401 0.1200
    """
    return if_then_else(
        time() < 2015,
        lambda: 0.0955,
        lambda: if_then_else(
            time() < 2016,
            lambda: 0.0835,
            lambda: if_then_else(
                time() < 2017,
                lambda: 0.0754,
                lambda: if_then_else(
                    time() < 2018,
                    lambda: 0.0673,
                    lambda: if_then_else(
                        time() < 2019,
                        lambda: 0.0704,
                        lambda: if_then_else(
                            time() < 2020,
                            lambda: 0.0721,
                            lambda: if_then_else(
                                time() < 2021,
                                lambda: 0.0656,
                                lambda: if_then_else(
                                    time() < 2022,
                                    lambda: 0.0754,
                                    lambda: if_then_else(
                                        time() < 2023,
                                        lambda: 0.1288,
                                        lambda: if_then_else(
                                            time() < 2024,
                                            lambda: 0.1401,
                                            lambda: if_then_else(
                                                time() < 2025,
                                                lambda: 0.12,
                                                lambda: 0.075
                                                * pv_uncertain_remunaration_factor()
                                                + fit()
                                                + cantonal_pv_support() * 0.05,
                                            ),
                                        ),
                                    ),
                                ),
                            ),
                        ),
                    ),
                ),
            ),
        ),
    )


