@component.add(
    name="Utility HS no incentives",
    units="Dmnl",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "green_utility_factor": 4,
        "peer_effect_hs_factor": 4,
        "economic_utility_factor_no_incentives": 4,
        "house_value_factor": 4,
        "double_tech_factor": 4,
        "dummy_hs": 4,
        "dummy_pv_for_hp_factor": 1,
        "alpha_hp": 2,
    },
)
def utility_hs_no_incentives():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
            "PVpanel": _subscript_dict["PVpanel"],
        },
        ["District", "HS", "Performance", "Type", "PVpanel"],
    )
    value.loc[:, _subscript_dict["OldS"], :, :, :] = (
        green_utility_factor()
        .loc[:, _subscript_dict["OldS"], :, :]
        .rename({"HS": "OldS"})
        + peer_effect_hs_factor()
        .loc[_subscript_dict["OldS"], :, :]
        .rename({"HS": "OldS"})
        .transpose("District", "OldS", "Type")
        + economic_utility_factor_no_incentives()
        .loc[:, _subscript_dict["OldS"], :, :, :]
        .rename({"HS": "OldS"})
        + house_value_factor()
        .loc[:, _subscript_dict["OldS"]]
        .rename({"HS": "OldS"})
        .transpose("OldS", "Performance")
        + double_tech_factor().loc[_subscript_dict["OldS"]].rename({"HS": "OldS"})
        + dummy_hs().loc[_subscript_dict["OldS"]].rename({"HS": "OldS"})
    ).values
    except_subs = xr.zeros_like(value, dtype=bool)
    except_subs.loc[:, _subscript_dict["NewS"], :, :, :] = True
    except_subs.loc[:, ["HeatPump"], :, :, :] = False
    value.values[except_subs.values] = (
        green_utility_factor()
        .loc[:, _subscript_dict["NewS"], :, :]
        .rename({"HS": "NewS"})
        + peer_effect_hs_factor()
        .loc[_subscript_dict["NewS"], :, :]
        .rename({"HS": "NewS"})
        .transpose("District", "NewS", "Type")
        + economic_utility_factor_no_incentives()
        .loc[:, _subscript_dict["NewS"], :, :, :]
        .rename({"HS": "NewS"})
        + house_value_factor()
        .loc[:, _subscript_dict["NewS"]]
        .rename({"HS": "NewS"})
        .transpose("NewS", "Performance")
        + double_tech_factor().loc[_subscript_dict["NewS"]].rename({"HS": "NewS"})
        + dummy_hs().loc[_subscript_dict["NewS"]].rename({"HS": "NewS"})
    ).values[except_subs.loc[:, _subscript_dict["NewS"], :, :, :].values]
    value.loc[:, ["HeatPump"], :, :, ["PVyes"]] = (
        (
            green_utility_factor().loc[:, "HeatPump", :, :].reset_coords(drop=True)
            + peer_effect_hs_factor().loc["HeatPump", :, :].reset_coords(drop=True)
            + economic_utility_factor_no_incentives()
            .loc[:, "HeatPump", :, :, "PVyes"]
            .reset_coords(drop=True)
            + house_value_factor().loc[:, "HeatPump"].reset_coords(drop=True)
            + alpha_hp()
            + float(double_tech_factor().loc["HeatPump"])
            + dummy_pv_for_hp_factor()
            + float(dummy_hs().loc["HeatPump"])
        )
        .expand_dims({"RenSolution": ["HeatPump"]}, 1)
        .expand_dims({"PVpanel": ["PVyes"]}, 4)
        .values
    )
    value.loc[:, ["HeatPump"], :, :, ["PVno"]] = (
        (
            green_utility_factor().loc[:, "HeatPump", :, :].reset_coords(drop=True)
            + peer_effect_hs_factor().loc["HeatPump", :, :].reset_coords(drop=True)
            + economic_utility_factor_no_incentives()
            .loc[:, "HeatPump", :, :, "PVno"]
            .reset_coords(drop=True)
            + house_value_factor().loc[:, "HeatPump"].reset_coords(drop=True)
            + alpha_hp()
            + float(double_tech_factor().loc["HeatPump"])
            + float(dummy_hs().loc["HeatPump"])
        )
        .expand_dims({"RenSolution": ["HeatPump"]}, 1)
        .expand_dims({"PVpanel": ["PVno"]}, 4)
        .values
    )
    return value


