@component.add(
    name="Annualized Total Cost HS no incentives",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "investment_cost_hs_no_incentives": 1,
        "total_variable_costs_hs": 1,
        "lifetime": 1,
    },
)
def annualized_total_cost_hs_no_incentives():
    return (
        (
            investment_cost_hs_no_incentives()
            - total_variable_costs_hs().transpose(
                "HS", "District", "Performance", "Type", "PVpanel"
            )
        )
        / lifetime()
    ).transpose("District", "HS", "Performance", "Type", "PVpanel")


