@component.add(
    name="Investment cost HS",
    units="CHF",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "investment_cost_hs_no_incentives": 9,
        "grant_st": 4,
        "grant_pelletboiler_pellet": 1,
        "grant_hp_heatpump": 1,
        "grant_pelletboiler_woodst": 1,
        "grant_hp_hpst": 1,
        "grant_dh": 1,
    },
)
def investment_cost_hs():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
        },
        ["District", "HS", "Performance", "Type"],
    )
    value.loc[:, ["OilST"], :, :] = (
        (
            investment_cost_hs_no_incentives()
            .loc["OilST", :, :, :]
            .reset_coords(drop=True)
            - grant_st().transpose("District", "Performance", "Type")
        )
        .expand_dims({"NonRenSolution": ["OilST"]}, 1)
        .values
    )
    value.loc[:, ["GasST"], :, :] = (
        (
            investment_cost_hs_no_incentives()
            .loc["GasST", :, :, :]
            .reset_coords(drop=True)
            - grant_st().transpose("District", "Performance", "Type")
        )
        .expand_dims({"WithGeoConstraint": ["GasST"]}, 1)
        .values
    )
    value.loc[:, ["pellet"], :, :] = (
        (
            investment_cost_hs_no_incentives()
            .loc["pellet", :, :, :]
            .reset_coords(drop=True)
            - grant_pelletboiler_pellet().transpose("District", "Performance", "Type")
        )
        .expand_dims({"RenSolution": ["pellet"]}, 1)
        .values
    )
    value.loc[:, ["HeatPump"], :, :] = (
        (
            investment_cost_hs_no_incentives()
            .loc["HeatPump", :, :, :]
            .reset_coords(drop=True)
            - grant_hp_heatpump().transpose("District", "Performance", "Type")
        )
        .expand_dims({"RenSolution": ["HeatPump"]}, 1)
        .values
    )
    value.loc[:, ["WoodST"], :, :] = (
        (
            investment_cost_hs_no_incentives()
            .loc["WoodST", :, :, :]
            .reset_coords(drop=True)
            - grant_pelletboiler_woodst()
            - grant_st().transpose("District", "Performance", "Type")
        )
        .expand_dims({"RenSolution": ["WoodST"]}, 1)
        .values
    )
    value.loc[:, ["HPST"], :, :] = (
        (
            investment_cost_hs_no_incentives()
            .loc["HPST", :, :, :]
            .reset_coords(drop=True)
            - grant_hp_hpst()
            - grant_st().transpose("District", "Performance", "Type")
        )
        .expand_dims({"RenSolution": ["HPST"]}, 1)
        .values
    )
    value.loc[:, _subscript_dict["OldS"], :, :] = (
        investment_cost_hs_no_incentives()
        .loc[_subscript_dict["OldS"], :, :, :]
        .rename({"HS": "OldS"})
        .transpose("District", "OldS", "Performance", "Type")
        .values
    )
    value.loc[:, ["Wood"], :, :] = (
        investment_cost_hs_no_incentives()
        .loc["Wood", :, :, :]
        .reset_coords(drop=True)
        .expand_dims({"RenSolution": ["Wood"]}, 1)
        .values
    )
    value.loc[:, ["DH"], :, :] = (
        (
            investment_cost_hs_no_incentives()
            .loc["DH", :, :, :]
            .reset_coords(drop=True)
            - grant_dh().transpose("District", "Performance", "Type")
        )
        .expand_dims({"RenSolution": ["DH"]}, 1)
        .values
    )
    return value


@component.add(
    name="PV differential cost change",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 13},
)
def pv_differential_cost_change():
    """
    IF THEN ELSE( Time < 2012, -1.1256, IF THEN ELSE( Time < 2013, -0.4658, IF THEN ELSE( Time < 2014, -0.3231, IF THEN ELSE( Time < 2015, -0.726, IF THEN ELSE( Time < 2016, -0.2089, IF THEN ELSE( Time < 2017, -0.282, IF THEN ELSE( Time < 2018, -0.2637, IF THEN ELSE( Time < 2019, -0.2683, IF THEN ELSE( Time < 2020, -0.1564, IF THEN ELSE( Time < 2021, -0.0753, IF THEN ELSE( Time < 2025, -0.0468, IF THEN ELSE( Time < 2030, 0 , IF THEN ELSE( Time < 2035, 0 , IF THEN ELSE( Time < 2040, 0 , IF THEN ELSE( Time < 2045, 0 , 0 )))))))))))))))
    """
    return if_then_else(
        time() < 2012,
        lambda: -1.1256,
        lambda: if_then_else(
            time() < 2013,
            lambda: -0.4658,
            lambda: if_then_else(
                time() < 2014,
                lambda: -0.3231,
                lambda: if_then_else(
                    time() < 2015,
                    lambda: -0.726,
                    lambda: if_then_else(
                        time() < 2016,
                        lambda: -0.2089,
                        lambda: if_then_else(
                            time() < 2017,
                            lambda: -0.282,
                            lambda: if_then_else(
                                time() < 2018,
                                lambda: -0.2637,
                                lambda: if_then_else(
                                    time() < 2019,
                                    lambda: -0.2683,
                                    lambda: if_then_else(
                                        time() < 2020,
                                        lambda: -0.1564,
                                        lambda: if_then_else(
                                            time() < 2021,
                                            lambda: 0,
                                            lambda: if_then_else(
                                                time() < 2025,
                                                lambda: 0,
                                                lambda: if_then_else(
                                                    time() < 2030,
                                                    lambda: 0,
                                                    lambda: if_then_else(
                                                        time() < 2040,
                                                        lambda: 0,
                                                        lambda: 0,
                                                    ),
                                                ),
                                            ),
                                        ),
                                    ),
                                ),
                            ),
                        ),
                    ),
                ),
            ),
        ),
    )


@component.add(
    name="Owners adopting RCPv",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 1,
        "owned_buildings_with_rcpv": 1,
        "heating_solution": 3,
        "share_urban_buildings": 1,
        "owned_buildings_with_pv": 1,
        "owned_buildings_with_rcp": 1,
        "share_of_owned_houses": 1,
        "owned_buildings_with_rcpv_pvno": 1,
        "probability_adoption_rcpv_owners": 1,
        "share_of_buildings_with_suitable_roof": 1,
        "energy_community_scenario": 1,
    },
)
def owners_adopting_rcpv():
    return (
        if_then_else(
            time() < 2025,
            lambda: xr.DataArray(
                0,
                {
                    "District": _subscript_dict["District"],
                    "HS": _subscript_dict["HS"],
                    "Performance": _subscript_dict["Performance"],
                    "Type": _subscript_dict["Type"],
                },
                ["District", "HS", "Performance", "Type"],
            ),
            lambda: (
                sum(
                    heating_solution().rename(
                        {"PVpanel": "PVpanel!", "Battery": "Battery!"}
                    ),
                    dim=["PVpanel!", "Battery!"],
                )
                * share_of_buildings_with_suitable_roof()
                * share_of_owned_houses()
                - sum(
                    heating_solution()
                    .loc[:, :, :, :, "PVyes", :]
                    .reset_coords(drop=True)
                    .rename({"Battery": "Battery!"}),
                    dim=["Battery!"],
                )
                * (
                    owned_buildings_with_pv()
                    + owned_buildings_with_rcp()
                    + owned_buildings_with_rcpv()
                    + owned_buildings_with_rcpv_pvno()
                )
                / sum(
                    heating_solution()
                    .loc[:, :, :, :, "PVyes", :]
                    .reset_coords(drop=True)
                    .rename(
                        {
                            "HS": "HS!",
                            "Performance": "Performance!",
                            "Battery": "Battery!",
                        }
                    ),
                    dim=["HS!", "Performance!", "Battery!"],
                )
            )
            * probability_adoption_rcpv_owners()
            * share_urban_buildings(),
        )
        * energy_community_scenario()
    )


