@component.add(
    name="Utility HS",
    units="Dmnl",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "green_utility_factor": 3,
        "peer_effect_hs_factor": 3,
        "house_value_factor": 3,
        "economic_utility_factor": 3,
        "double_tech_factor": 3,
        "grid_hs_factor": 3,
        "dummy_hs": 3,
        "alpha_hp": 2,
        "dummy_pv_for_hp_factor": 1,
    },
)
def utility_hs():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
            "PVpanel": _subscript_dict["PVpanel"],
        },
        ["District", "HS", "Performance", "Type", "PVpanel"],
    )
    except_subs = xr.ones_like(value, dtype=bool)
    except_subs.loc[:, _subscript_dict["HPs"], :, :, :] = False
    value.values[except_subs.values] = (
        green_utility_factor()
        + peer_effect_hs_factor().transpose("District", "HS", "Type")
        + house_value_factor().transpose("HS", "Performance")
        + economic_utility_factor()
        + double_tech_factor()
        + grid_hs_factor()
        + dummy_hs()
    ).values[except_subs.values]
    value.loc[:, _subscript_dict["HPs"], :, :, ["PVno"]] = (
        (
            green_utility_factor()
            .loc[:, _subscript_dict["HPs"], :, :]
            .rename({"HS": "HPs"})
            + peer_effect_hs_factor()
            .loc[_subscript_dict["HPs"], :, :]
            .rename({"HS": "HPs"})
            .transpose("District", "HPs", "Type")
            + house_value_factor()
            .loc[:, _subscript_dict["HPs"]]
            .rename({"HS": "HPs"})
            .transpose("HPs", "Performance")
            + economic_utility_factor()
            .loc[:, _subscript_dict["HPs"], :, :, "PVno"]
            .reset_coords(drop=True)
            .rename({"HS": "HPs"})
            + alpha_hp()
            + double_tech_factor().loc[_subscript_dict["HPs"]].rename({"HS": "HPs"})
            + grid_hs_factor().loc[_subscript_dict["HPs"]].rename({"HS": "HPs"})
            + dummy_hs().loc[_subscript_dict["HPs"]].rename({"HS": "HPs"})
        )
        .expand_dims({"PVpanel": ["PVno"]}, 4)
        .values
    )
    value.loc[:, _subscript_dict["HPs"], :, :, ["PVyes"]] = (
        (
            green_utility_factor()
            .loc[:, _subscript_dict["HPs"], :, :]
            .rename({"HS": "HPs"})
            + peer_effect_hs_factor()
            .loc[_subscript_dict["HPs"], :, :]
            .rename({"HS": "HPs"})
            .transpose("District", "HPs", "Type")
            + house_value_factor()
            .loc[:, _subscript_dict["HPs"]]
            .rename({"HS": "HPs"})
            .transpose("HPs", "Performance")
            + economic_utility_factor()
            .loc[:, _subscript_dict["HPs"], :, :, "PVno"]
            .reset_coords(drop=True)
            .rename({"HS": "HPs"})
            + alpha_hp()
            + double_tech_factor().loc[_subscript_dict["HPs"]].rename({"HS": "HPs"})
            + grid_hs_factor().loc[_subscript_dict["HPs"]].rename({"HS": "HPs"})
            + dummy_pv_for_hp_factor()
            + dummy_hs().loc[_subscript_dict["HPs"]].rename({"HS": "HPs"})
        )
        .expand_dims({"PVpanel": ["PVyes"]}, 4)
        .values
    )
    return value


