@component.add(
    name="Ground High scaled",
    subscripts=["District", "Type", "Performance"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"ground_high_scaled": 2, "ground_high": 3, "coeff_high": 1},
)
def ground_high_scaled():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "Type": _subscript_dict["Type"],
            "Performance": _subscript_dict["Performance"],
        },
        ["District", "Type", "Performance"],
    )
    except_subs = xr.zeros_like(value, dtype=bool)
    except_subs.loc[:, :, _subscript_dict["PerformanceHigh"]] = True
    except_subs.loc[:, :, ["Moderate"]] = False
    value.values[except_subs.values] = (
        (
            ground_high()
            .loc[:, :, _subscript_dict["PerformanceHigh"]]
            .rename({"Performance": "PerformanceHigh"})
            - (
                (
                    vmax(
                        ground_high().rename({"Performance": "Performance!"}),
                        dim=["Performance!"],
                    )
                    - vmin(
                        ground_high().rename({"Performance": "Performance!"}),
                        dim=["Performance!"],
                    )
                )
                / 2
            )
        )
        / 10000
        + coeff_high()
        .loc[:, _subscript_dict["PerformanceHigh"]]
        .rename({"Performance": "PerformanceHigh"})
    ).values[except_subs.loc[:, :, _subscript_dict["PerformanceHigh"]].values]


    value.loc[:, :, _subscript_dict["PerformanceLow"]] = (
        value
        .loc[:, :, "High"]
        .reset_coords(drop=True)
        .expand_dims({"PerformanceLow": _subscript_dict["PerformanceLow"]}, 2)
        .values
    )
    value.loc[:, :, ["Moderate"]] = (
        value
        .loc[:, :, "High"]
        .reset_coords(drop=True)
        .expand_dims({"PerformanceHigh": ["Moderate"]}, 2)
        .values
    )
    return value
