@component.add(
    name="Annual cost Cantonal Levy by arch",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel", "Battery"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "heating_solution": 7,
        "el_consumption_per_building": 7,
        "cantonal_levy_evolution": 4,
        "rented_buildings_with_rcpv_pvno": 1,
        "owned_buildings_with_rcpv_pvno": 1,
        "self_consumption_degree_rcpv": 2,
        "pv_annual_generation_per_building_rcpv": 3,
        "share_primary_houses": 3,
        "buildings_rcpv_by_archetype": 4,
        "self_consumption_degree_with_storage": 1,
        "self_consumption_degree_with_storage_rcpv": 1,
        "time": 2,
        "pv_annual_generation_per_building": 2,
        "self_consumption_degree": 1,
    },
)
def annual_cost_cantonal_levy_by_arch():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
            "PVpanel": _subscript_dict["PVpanel"],
            "Battery": _subscript_dict["Battery"],
        },
        ["District", "HS", "Performance", "Type", "PVpanel", "Battery"],
    )
    value.loc[:, :, :, :, ["PVno"], :] = (
        np.maximum(
            0,
            (
                heating_solution().loc[:, :, :, :, "PVno", :].reset_coords(drop=True)
                * el_consumption_per_building()
                * cantonal_levy_evolution()
                - heating_solution().loc[:, :, :, :, "PVno", :].reset_coords(drop=True)
                * (owned_buildings_with_rcpv_pvno() + rented_buildings_with_rcpv_pvno())
                / sum(
                    heating_solution()
                    .loc[:, :, :, :, "PVno", :]
                    .reset_coords(drop=True)
                    .rename(
                        {
                            "HS": "HS!",
                            "Performance": "Performance!",
                            "Battery": "Battery!",
                        }
                    ),
                    dim=["HS!", "Performance!", "Battery!"],
                )
                * pv_annual_generation_per_building_rcpv()
                * 0.8
                * self_consumption_degree_rcpv()
                * cantonal_levy_evolution()
            )
            * share_primary_houses(),
        )
        .expand_dims({"PVpanel": ["PVno"]}, 4)
        .values
    )
    value.loc[:, :, :, :, ["PVyes"], ["Byes"]] = (
        np.maximum(
            0,
            if_then_else(
                time() < 2015,
                lambda: heating_solution()
                .loc[:, :, :, :, "PVyes", "Byes"]
                .reset_coords(drop=True)
                * el_consumption_per_building(),
                lambda: (
                    heating_solution()
                    .loc[:, :, :, :, "PVyes", "Byes"]
                    .reset_coords(drop=True)
                    - buildings_rcpv_by_archetype()
                    .loc[:, :, :, :, "Byes"]
                    .reset_coords(drop=True)
                )
                * (
                    el_consumption_per_building()
                    - (
                        pv_annual_generation_per_building()
                        * self_consumption_degree_with_storage().transpose(
                            "District", "Type", "HS", "Performance"
                        )
                    ).transpose("District", "HS", "Performance", "Type")
                )
                + buildings_rcpv_by_archetype()
                .loc[:, :, :, :, "Byes"]
                .reset_coords(drop=True)
                * (
                    el_consumption_per_building()
                    - (
                        pv_annual_generation_per_building_rcpv()
                        * self_consumption_degree_with_storage_rcpv().transpose(
                            "District", "Type", "HS", "Performance"
                        )
                    ).transpose("District", "HS", "Performance", "Type")
                ),
            )
            * cantonal_levy_evolution()
            * share_primary_houses(),
        )
        .expand_dims({"PVpanel": ["PVyes"]}, 4)
        .expand_dims({"Battery": ["Byes"]}, 5)
        .values
    )
    value.loc[:, :, :, :, ["PVyes"], ["Bno"]] = (
        np.maximum(
            0,
            if_then_else(
                time() < 2015,
                lambda: heating_solution()
                .loc[:, :, :, :, "PVyes", "Bno"]
                .reset_coords(drop=True)
                * el_consumption_per_building(),
                lambda: (
                    heating_solution()
                    .loc[:, :, :, :, "PVyes", "Bno"]
                    .reset_coords(drop=True)
                    - buildings_rcpv_by_archetype()
                    .loc[:, :, :, :, "Bno"]
                    .reset_coords(drop=True)
                )
                * (
                    el_consumption_per_building()
                    - (
                        pv_annual_generation_per_building()
                        * self_consumption_degree().transpose(
                            "District", "Type", "HS", "Performance"
                        )
                    ).transpose("District", "HS", "Performance", "Type")
                )
                + buildings_rcpv_by_archetype()
                .loc[:, :, :, :, "Bno"]
                .reset_coords(drop=True)
                * (
                    el_consumption_per_building()
                    - (
                        pv_annual_generation_per_building_rcpv()
                        * self_consumption_degree_rcpv().transpose(
                            "District", "Type", "HS", "Performance"
                        )
                    ).transpose("District", "HS", "Performance", "Type")
                ),
            )
            * cantonal_levy_evolution()
            * share_primary_houses(),
        )
        .expand_dims({"PVpanel": ["PVyes"]}, 4)
        .expand_dims({"Battery": ["Bno"]}, 5)
        .values
    )
    return value


