@component.add(
    name="PV Eco Owners factor",
    units="Dmnl",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"pv_eco_utility_owners": 1, "pv_eco_weight": 1},
)
def pv_eco_owners_factor():
    return pv_eco_utility_owners() * pv_eco_weight()


@component.add(
    name="PV federal investment grant capacity",
    units="CHF/kW",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 10},
)
def pv_federal_investment_grant_capacity():
    """
    IF THEN ELSE(Time < 2014.25, 0, IF THEN ELSE(Time < 2015, 1050, IF THEN ELSE(Time < 2016, 830, IF THEN ELSE(Time < 2017, 610, IF THEN ELSE(Time < 2018, 520, IF THEN ELSE(Time < 2019, 460, IF THEN ELSE(Time < 2020, 380, IF THEN ELSE(Time < 2021, 380, IF THEN ELSE(Time < 2022, 420 , SMOOTH( IF THEN ELSE(Time < 2035, Sensitivity 1 , 0 ) , 1 ) )))))))))
    """
    return if_then_else(
        time() < 2014,
        lambda: 0,
        lambda: if_then_else(
            time() < 2015,
            lambda: 1050,
            lambda: if_then_else(
                time() < 2016,
                lambda: 830,
                lambda: if_then_else(
                    time() < 2017,
                    lambda: 610,
                    lambda: if_then_else(
                        time() < 2018,
                        lambda: 520,
                        lambda: if_then_else(
                            time() < 2019,
                            lambda: 460,
                            lambda: if_then_else(
                                time() < 2020,
                                lambda: 380,
                                lambda: if_then_else(
                                    time() < 2021,
                                    lambda: 380,
                                    lambda: if_then_else(
                                        time() < 2026,
                                        lambda: 420,
                                        lambda: if_then_else(
                                            time() < 2030, lambda: 420, lambda: 420
                                        ),
                                    ),
                                ),
                            ),
                        ),
                    ),
                ),
            ),
        ),
    )


@component.add(
    name="PV annual mantainance cost",
    units="CHF/kWh",
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 2, "tax_deduction_om": 1},
)
def pv_annual_mantainance_cost():
    return (
        if_then_else(
            time() < 2024,
            lambda: 3.87 - (3.87 - 2.38) / (2024 - 2011) * (time() - 2011),
            lambda: 2.38,
        )
        * (1 - tax_deduction_om())
        / 100
    )


