@component.add(
    name="Carrier used cost per kWh",
    units="CHF/l",
    subscripts=["District", "Tech"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "time": 6,
        "historical_carrier_cost": 10,
        "additional_oil_unit_cost_co2_tax": 2,
        "oilgas_carrier_cost_uncertainty_factor": 2,
        "additional_gas_unit_cost_co2_tax": 2,
        "woodpellet_carrier_cost_uncertainty_factor": 2,
        "electricity_price": 2,
    },
)
def carrier_used_cost_per_kwh():
    value = xr.DataArray(
        np.nan,
        {"District": _subscript_dict["District"], "Tech": _subscript_dict["Tech"]},
        ["District", "Tech"],
    )
    value.loc[:, ["OilBoiler"]] = (
        if_then_else(
            time() < 2023,
            lambda: float(historical_carrier_cost().loc["OilBoiler"]),
            lambda: if_then_else(
                time() < 2026,
                lambda: float(historical_carrier_cost().loc["OilBoiler"])
                + additional_oil_unit_cost_co2_tax(),
                lambda: float(historical_carrier_cost().loc["OilBoiler"])
                + additional_oil_unit_cost_co2_tax(),
            ),
        )
        * oilgas_carrier_cost_uncertainty_factor()
    )
    value.loc[:, ["GasBoiler"]] = (
        if_then_else(
            time() < 2023,
            lambda: float(historical_carrier_cost().loc["GasBoiler"]),
            lambda: if_then_else(
                time() < 2026,
                lambda: float(historical_carrier_cost().loc["GasBoiler"])
                + additional_gas_unit_cost_co2_tax(),
                lambda: float(historical_carrier_cost().loc["GasBoiler"])
                + additional_gas_unit_cost_co2_tax(),
            ),
        )
        * oilgas_carrier_cost_uncertainty_factor()
    )
    value.loc[:, ["PelletBoiler"]] = (
        if_then_else(
            time() < 2026,
            lambda: float(historical_carrier_cost().loc["PelletBoiler"]),
            lambda: float(historical_carrier_cost().loc["PelletBoiler"]),
        )
        * woodpellet_carrier_cost_uncertainty_factor()
    )
    value.loc[:, ["HP"]] = electricity_price().expand_dims({"Tech": ["HP"]}, 1).values
    value.loc[:, ["EH"]] = electricity_price().expand_dims({"Tech": ["EH"]}, 1).values
    value.loc[:, ["ST"]] = 0
    value.loc[:, ["WoodBoiler"]] = (
        if_then_else(
            time() < 2026,
            lambda: float(historical_carrier_cost().loc["WoodBoiler"]),
            lambda: float(historical_carrier_cost().loc["WoodBoiler"]),
        )
        * woodpellet_carrier_cost_uncertainty_factor()
    )
    return value


@component.add(
    name="Efficiency",
    units="Dmnl",
    subscripts=["Tech"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={"hp_efficiency_uncertainty_factor": 1},
)
def efficiency():
    value = xr.DataArray(np.nan, {"Tech": _subscript_dict["Tech"]}, ["Tech"])
    value.loc[["OilBoiler"]] = 0.9
    value.loc[["GasBoiler"]] = 0.95
    value.loc[["PelletBoiler"]] = 0.9
    value.loc[["HP"]] = 3.4 * hp_efficiency_uncertainty_factor()
    value.loc[["EH"]] = 0.95
    value.loc[["ST"]] = 1
    value.loc[["WoodBoiler"]] = 0.72
    return value


@component.add(
    name="Lifetime",
    units="year",
    subscripts=["HS"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "oilgas_lifetime_uncertainty_factor": 4,
        "woodpellet_lifetime_uncertainty_factor": 3,
        "hp_lifetime_uncertainty_factor": 2,
    },
)
def lifetime():
    value = xr.DataArray(np.nan, {"HS": _subscript_dict["HS"]}, ["HS"])
    value.loc[["Oil"]] = 20 * oilgas_lifetime_uncertainty_factor()
