@component.add(
    name="Annual DHW demand by arch",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "annual_dhw_demand": 1,
        "heating_solution": 1,
        "share_primary_houses": 1,
    },
)
def annual_dhw_demand_by_arch():
    return (
        annual_dhw_demand()
        * sum(
            heating_solution().rename({"PVpanel": "PVpanel!", "Battery": "Battery!"}),
            dim=["PVpanel!", "Battery!"],
        ).transpose("District", "Type", "HS", "Performance")
        * share_primary_houses()
    ).transpose("District", "HS", "Performance", "Type")


@component.add(
    name="Annual SH demand",
    units="kWh/year",
    subscripts=["District", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"average_building_size": 1, "specific_sh_demand": 1},
)
def annual_sh_demand():
    return (average_building_size() * specific_sh_demand()).transpose(
        "District", "Performance", "Type"
    )


@component.add(
    name="Technology DHW installed capacity SH and DHW",
    units="kW",
    subscripts=["District", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"annual_dhw_demand": 1, "equivalent_hours_sh_and_dhw": 1},
)
def technology_dhw_installed_capacity_sh_and_dhw():
    return annual_dhw_demand() / equivalent_hours_sh_and_dhw()


@component.add(
    name="Annualized Total Cost HS",
    units="CHF",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"investment_cost_hs": 1, "total_variable_costs_hs": 1, "lifetime": 1},
)
def annualized_total_cost_hs():
    return (investment_cost_hs() - total_variable_costs_hs()) / lifetime()


@component.add(
    name="Residential electricity cons DHW per building",
    units="kWh",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "annual_dhw_demand": 3,
        "efficiency": 3,
        "efficiency_dhw_storage": 2,
        "st_share_of_total_heat_production": 1,
    },
)
def residential_electricity_cons_dhw_per_building():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
        },
        ["District", "HS", "Performance", "Type"],
    )
    value.loc[:, ["HeatPump"], :, :] = (
        (annual_dhw_demand() / float(efficiency().loc["HP"]) / efficiency_dhw_storage())
        .expand_dims({"RenSolution": ["HeatPump"]}, 1)
        .expand_dims({"Performance": _subscript_dict["Performance"]}, 2)
        .values
    )
    value.loc[:, ["HPST"], :, :] = (
        (
            (1 - st_share_of_total_heat_production())
            * annual_dhw_demand()
            / float(efficiency().loc["HP"])
        )
        .expand_dims({"RenSolution": ["HPST"]}, 1)
        .expand_dims({"Performance": _subscript_dict["Performance"]}, 2)
        .values
    )
    value.loc[:, ["ElectricHeater"], :, :] = (
        (annual_dhw_demand() / float(efficiency().loc["EH"]) / efficiency_dhw_storage())
        .expand_dims({"NonRenSolution": ["ElectricHeater"]}, 1)
        .expand_dims({"Performance": _subscript_dict["Performance"]}, 2)
        .values
    )
    value.loc[:, _subscript_dict["No Electricity"], :, :] = 0
    return value


@component.add(
    name="Economic Utility HS",
    units="Dmnl",
    subscripts=["District", "HS", "Performance", "Type", "PVpanel"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={"annualized_total_cost_hs": 4},
)
def economic_utility_hs():
    return (
        annualized_total_cost_hs()
        - vmin(annualized_total_cost_hs().rename({"HS": "HS!"}), dim=["HS!"])
    ) / (
        vmax(annualized_total_cost_hs().rename({"HS": "HS!"}), dim=["HS!"])
        - vmin(annualized_total_cost_hs().rename({"HS": "HS!"}), dim=["HS!"])
    )


@component.add(
    name="El consumption per building",
    units="kWh/year",
    subscripts=["District", "HS", "Performance", "Type"],
    comp_type="Auxiliary",
    comp_subtype="Normal",
    depends_on={
        "annual_light_and_appl_demand_by_arch": 4,
        "annual_sh_demand": 3,
        "efficiency_dhw_storage": 2,
        "annual_dhw_demand": 3,
        "efficiency": 3,
        "annual_electricity_consumption_per_building_evs": 4,
        "st_share_of_total_heat_production": 1,
    },
)
def el_consumption_per_building():
    value = xr.DataArray(
        np.nan,
        {
            "District": _subscript_dict["District"],
            "HS": _subscript_dict["HS"],
            "Performance": _subscript_dict["Performance"],
            "Type": _subscript_dict["Type"],
        },
        ["District", "HS", "Performance", "Type"],
    )
    value.loc[:, ["HeatPump"], :, :] = (
        (
            annual_light_and_appl_demand_by_arch()
            + (
                (annual_sh_demand() + (annual_dhw_demand() / efficiency_dhw_storage()))
                / float(efficiency().loc["HP"])
            ).transpose("Performance", "District", "Type")
            + annual_electricity_consumption_per_building_evs()
        )
        .transpose("District", "Performance", "Type")
        .expand_dims({"RenSolution": ["HeatPump"]}, 1)
        .values
    )
    value.loc[:, ["HPST"], :, :] = (
        (
            annual_light_and_appl_demand_by_arch()
            + (
                (
                    annual_sh_demand()
                    + ((1 - st_share_of_total_heat_production()) * annual_dhw_demand())
                )
                / float(efficiency().loc["HP"])
            ).transpose("Performance", "District", "Type")
            + annual_electricity_consumption_per_building_evs()
        )
        .transpose("District", "Performance", "Type")
        .expand_dims({"RenSolution": ["HPST"]}, 1)
        .values
    )
    value.loc[:, ["ElectricHeater"], :, :] = (
        (
            annual_light_and_appl_demand_by_arch()
            + (
                (annual_sh_demand() + (annual_dhw_demand() / efficiency_dhw_storage()))
                / float(efficiency().loc["EH"])
            ).transpose("Performance", "District", "Type")
            + annual_electricity_consumption_per_building_evs()
        )
        .transpose("District", "Performance", "Type")
        .expand_dims({"NonRenSolution": ["ElectricHeater"]}, 1)
        .values
    )
    value.loc[:, _subscript_dict["No Electricity"], :, :] = (
        (
            annual_light_and_appl_demand_by_arch()
            + annual_electricity_consumption_per_building_evs()
        )
        .transpose("District", "Performance", "Type")
        .expand_dims({"No Electricity": _subscript_dict["No Electricity"]}, 1)
        .values
    )
    return value


