@component.add(
    name='"Initial grant < 15 kW"',
    units="CHF",
    subscripts=["Tech"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 10},
)
def initial_grant_15_kw_1():
    value = xr.DataArray(np.nan, {"Tech": _subscript_dict["Tech"]}, ["Tech"])
    value.loc[["OilBoiler"]] = 0
    value.loc[["GasBoiler"]] = 0
    value.loc[["PelletBoiler"]] = if_then_else(
        time() < 2022,
        lambda: 0,
        lambda: if_then_else(
            time() < 2025,
            lambda: 5000,
            lambda: if_then_else(time() < 2030, lambda: 7000, lambda: 7000),
        ),
    )
    value.loc[["HP"]] = if_then_else(
        time() < 2017,
        lambda: 3000,
        lambda: if_then_else(
            time() < 2022,
            lambda: 4000,
            lambda: if_then_else(time() < 2030, lambda: 7000, lambda: 7000),
        ),
    )
    value.loc[["EH"]] = 0
    value.loc[["ST"]] = if_then_else(
        time() < 2017,
        lambda: 2500,
        lambda: if_then_else(
            time() < 2022,
            lambda: 1200,
            lambda: if_then_else(
                time() < 2025,
                lambda: 2500,
                lambda: if_then_else(time() < 2030, lambda: 2400, lambda: 2400),
            ),
        ),
    )
    value.loc[["WoodBoiler"]] = 0
    return value


@component.add(
    name='"Investment grant per kW < 15 kW"',
    units="CHF/kW",
    subscripts=["Tech"],
    comp_type="Constant, Auxiliary",
    comp_subtype="Normal",
    depends_on={"time": 9},
)
def investment_grant_per_kw_15_kw_1():
    """
    IF THEN ELSE(Time < 2016.1, 0, IF THEN ELSE(Time < 2021.1, 100, IF THEN ELSE(Time < 2030 , 180 , 180 ) ) )
    """
    value = xr.DataArray(np.nan, {"Tech": _subscript_dict["Tech"]}, ["Tech"])
    value.loc[["OilBoiler"]] = 0
    value.loc[["GasBoiler"]] = 0
    value.loc[["PelletBoiler"]] = if_then_else(
        time() < 2022,
        lambda: 0,
        lambda: if_then_else(
            time() < 2025,
            lambda: 100,
            lambda: if_then_else(time() < 2030, lambda: 0, lambda: 0),
        ),
    )
    value.loc[["HP"]] = if_then_else(
        time() < 2017,
        lambda: 0,
        lambda: if_then_else(
            time() < 2022,
            lambda: 100,
            lambda: if_then_else(time() < 2030, lambda: 300, lambda: 0),
        ),
    )
    value.loc[["EH"]] = 0
    value.loc[["ST"]] = if_then_else(
        time() < 2016.1,
        lambda: 0,
        lambda: if_then_else(
            time() < 2021.1,
            lambda: 200,
            lambda: if_then_else(time() < 2030, lambda: 500, lambda: 0),
        ),
    )
    value.loc[["WoodBoiler"]] = 0
    return value


@component.add(
    name="Emissions per capacity installed",
    units="CO2eq/kW",
    subscripts=["Tech"],
    comp_type="Constant",
    comp_subtype="Normal",
)
def emissions_per_capacity_installed():
    value = xr.DataArray(np.nan, {"Tech": _subscript_dict["Tech"]}, ["Tech"])
    value.loc[["OilBoiler"]] = 21.1
    value.loc[["GasBoiler"]] = 21.1
    value.loc[["PelletBoiler"]] = 21.1
    value.loc[["HP"]] = 164.9
    value.loc[["EH"]] = 1.47
    value.loc[["ST"]] = 221.2
    value.loc[["WoodBoiler"]] = 21.1
    return value
